const int sqrt_c(const int x){
	int l=0;
	int r=MAXN;
	int mid;
	while(1){
		if(r-l==1){
			return l;
		}
		mid=(l+r)>>1;
		if(mid*mid<=x){
			l=mid;
		}else{
			r=mid;
		}
	}
}

