bool log2n_flag=1;
int log2n_[MAXN];

inline void log2n_init(void){
	log2n_[0]=log2n_[1]=0;
	for(int i=2;i<MAXN;i++){
		log2n_[i]=log2n_[i>>1]+1;
	}
	log2n_flag=0;
}

const int log2n(const int n){
	if(log2n_flag){
		log2n_init();
	}
	return log2n_[n];
}

const bool kth_bool(const int n,const int k){
	return bool(n&(1<<k));
