template <typename cactus>
const cactus gcd_c(const cactus& a,const cactus& b){
	cactus a_=a,b_=b,t;
	while(b_){
		t=b_;
		b_=a_%b_;
		a_=t;
	}
	return a_;
}

template <typename cactus>
const cactus lcm_c(const cactus& a,const cactus& b){
	return a/gcd_c(a,b)*b;
}

template <typename cactus,typename cactusx>
const cactus pow_c(const cactus& a,const cactusx& n){//a^n
	cactus ret=0;
	cactus temp=a;
	cactusx n_=n;
	while(n_){
		if(n_&1){
			ret+=temp;
		}
		temp*=temp;
		n_>>1;
	}
	return ret;
}

template <typename cactus,typename cactusx>
const cactus pow_c(const cactus& a,const cactusx& n,const cactus& mod){//a^n
	cactus ret=0;
	cactus temp=a%mod;
	cactusx n_=n;
	while(n_){
		if(n_&1){
			ret+=temp;
			ret%=mod;
		}
		temp=(temp*temp)%mod;
		n_>>1;
	}
	return ret;
}

int pri_phif[MAXN];
int cnt_phif=0;
int ph_phif[MAXN]={0,1};
bool vis_phif[MAXN];
int flag_phif=2;
const int phi(const int n){
	if(n<flag_phif){
		return ph_phif[n];
	}
	for(;flag_phif<=n;flag_phif++){
		if(!vis_phif[flag_phif]){
			cnt_phif++;
			pri_phif[cnt_phif]=flag_phif;
			ph_phif[flag_phif]=flag_phif-1;
		}
		for(int j=1;j<=cnt_phif;j++){
			if(pri_phif[j]*flag_phif>=MAXN-3)break;
			vis_phif[pri_phif[j]*flag_phif]=1;
			if(flag_phif%pri_phif[j]){
				ph_phif[pri_phif[j]*flag_phif]=ph_phif[flag_phif]*(pri_phif[j]-1);
			}else{
				ph_phif[pri_phif[j]*flag_phif]=ph_phif[flag_phif]*pri_phif[j];
				break;
			}
		}
	}
	return ph_phif[n];
}

const int prime(const int id){
	if(id<=cnt_phif){
		return pri_phif[id];
	}
	for(;cnt_phif<=id;flag_phif++){
		if(!vis_phif[flag_phif]){
			cnt_phif++;
			pri_phif[cnt_phif]=flag_phif;
			ph_phif[flag_phif]=flag_phif-1;
		}
		for(int j=1;j<=cnt_phif;j++){
			if(pri_phif[j]*flag_phif>=MAXN-3)break;
			vis_phif[pri_phif[j]*flag_phif]=1;
			if(flag_phif%pri_phif[j]){
				ph_phif[pri_phif[j]*flag_phif]=ph_phif[flag_phif]*(pri_phif[j]-1);
			}else{
				ph_phif[pri_phif[j]*flag_phif]=ph_phif[flag_phif]*pri_phif[j];
				break;
			}
		}
	}
	return pri_phif[id];
}

