inline void qread(int &rd){
	int sgn=1;
	int ret=0;
	char r=getchar();
	while(notnum(r)&&r!='-'){
		r=getchar();
	}
	if(r=='-'){
		sgn=-1;
	}else{
		ret=r-'0';
	}
	r=getchar();
	while(isnum(r)){
		ret*=10;
		ret+=r-'0';
		r=getchar();
	}
	rd=sgn*ret;
}

