inline const bool char_in_end(const char c){
	return c=='\n'||c==' ';
}

inline void qread(char &rd){
	rd=getchar();
	while(char_in_end(rd)){
		rd=getchar();
	}
}

inline void qread(string &rd){
	char gt=getchar();
	rd="";
	while(char_in_end(gt)){
		gt=getchar();
	}
	while(!char_in_end(gt)){
		rd+=gt;
		gt=getchar();
	}
}

inline void qread(char *rd){
	char gt=getchar();
	while(char_in_end(gt)){
		gt=getchar();
	}
	while(!char_in_end(gt)){
		*rd+=gt;
		rd++;
		gt=getchar();
	}
	*rd='\0';
}

