template <typename cactus>
//queue
class queue_c{
	private:
		cactus q[MAXN+5];
		int head,tail;
		int inq;
	public:
		queue_c(void);
		queue_c(const cactus v);
		queue_c(cactus *p1,cactus *p2);
		const SIZE_C size(void);
		void insert(const cactus v);
		void pop(void);
		const cactus front(void);
		void clear(void);
		void pop(const int cnt);
		const bool empty(void);
};

template <typename cactus>
queue_c<cactus>::queue_c(void){
	head=0;
	tail=-1;
	inq=0;
}

template <typename cactus>
queue_c<cactus>::queue_c(const cactus v){
	head=0;
	tail=0;
	inq=1;
	q[0]=v;
}

template <typename cactus>
queue_c<cactus>::queue_c(cactus *p1,cactus *p2){
	head=0;
	inq=*p2-*p1;
	for(int i=0;i<inq;i++,p1++){
		q[i]=*p1;
	}
	tail=inq-1;
}

template <typename cactus>
const SIZE_C queue_c<cactus>::size(void){
	return inq;
}

template <typename cactus>
void queue_c<cactus>::insert(const cactus v){
	inq++;
	if(tail==MAXN){
		tail=0;
	}else{
		tail++;
	}
	q[tail]=v;
}

template <typename cactus>
void queue_c<cactus>::pop(void){
	if(!inq)return;
	inq--;
	if(head==MAXN){
		head=0;
	}else{
		head++;
	}
}

template <typename cactus>
const cactus queue_c<cactus>::front(void){
	return q[head];
}

template <typename cactus>
void queue_c<cactus>::clear(void){
	head=0;
	tail=-1;
}

template <typename cactus>
void queue_c<cactus>::pop(const int cnt){
	if(cnt>=inq){
		*this->clear();
	}else{
		head+=cnt;
		if(head>MAXN){
			head-=MAXN;
			head--;
		}
	}
}

template <typename cactus>
const bool queue_c<cactus>::empty(void){
	return !(bool)inq;
}

