class stack_c{
	private:
		cactus s[MAXN+5]; 
		int ins;
		int head;
	public:
		stack_c(void);
		stack_c(const cactus v);
		stack_c(cactus *p1,cactus *p2);
		const SIZE_C size(void);
		void pop(void);
		void insert(const cactus v);
		const cactus top(void);
		void clear(void);
		const bool empty(void);
};

template <typename cactus>
stack_c<cactus>::stack_c(void){
	head=-1;
	ins=0;
}

template <typename cactus>
stack_c<cactus>::stack_c(const cactus v){
	head=0;
	ins=1;
	s[0]=v;
}

template <typename cactus>
stack_c<cactus>::stack_c(cactus *p1,cactus *p2){
	ins=p2-p1;
	head=ins-1;
	for(int i=0;i<ins;i++){
		s[i]=*p1;
		p1++;
	}
}

template <typename cactus>
const SIZE_C stack_c<cactus>::size(void){
	return ins;
}

template <typename cactus>
void stack_c<cactus>::pop(void){
	if(!ins) return;
	head--;
	ins--;
}

template <typename cactus>
void stack_c<cactus>::insert(const cactus v){
	s[ins]=v;
	ins++;
	head++;
}

template <typename cactus>
const cactus stack_c<cactus>::top(void){
	return s[head];
}

template <typename cactus>
void stack_c<cactus>::clear(void){
	ins=0;
	head=-1;
}

template <typename cactus>
const bool stack_c<cactus>::empty(void){
