template <typename cactus>
class min_mono_queue{
	private:
		int n,k;
		cactus mina[MAXN];
	public:
		explicit min_mono_queue(cactus *c1,cactus* c2,const int length_);
		const cactus min(const int pos);//starting from pos
};

template <typename cactus>
min_mono_queue<cactus>::min_mono_queue(cactus *c1,cactus* c2,const int length_){
	k=length_;
	n=c2-c1;
	if(k==1){
		for(int i=1;i<=n;i++){
			mina[i]=*c1;
			c1++;
		}
	}else{
		deque_c <int> qmin;
		qmin.insert_front(1);
		for(int i=2;i<=n;i++){
			if(qmin.front()==i-k){
				qmin.pop_front();
			}
			while(!qmin.empty()&&(c1[qmin.back()-1]>c1[i-1])){
				qmin.pop_back();
			}
			qmin.insert_back(i);
			mina[i]=qmin.front();
		}
	}
}

template <typename cactus>
const cactus min_mono_queue<cactus>::min(const int pos){
	return mina[pos-k+1];
}



