	public:
		T_1 x1;
		T_2 x2;

		pair_c(void){}
		pair_c(T_1 t1,T_2 t2);
		const bool operator>(const pair_c p)const;
		const bool operator<(const pair_c p)const;
		const bool operator>=(const pair_c p)const;
		const bool operator<=(const pair_c p)const;
		const bool operator==(const pair_c p);
		const bool operator!=(const pair_c p);
};

template <typename T_1,typename T_2>
pair_c<T_1,T_2>::pair_c(T_1 t1,T_2 t2){
	x1=t1;
	x2=t2;
}

template <typename T_1,typename T_2>
const bool pair_c<T_1,T_2>::operator>(const pair_c p)const{
	if(x1>p.x1){
		return true;
	}else{
		if(x1<p.x1){
			return false;
		}else{
			if(x2<p.x2){
				return false;
			}else{
				if(x2>p.x2){
					return true;
				}else{
					return false;
				}
			}
		}
	}
}

template <typename T_1,typename T_2>
const bool pair_c<T_1,T_2>::operator<(const pair_c p)const{
	if(x1>p.x1){
		return false;
	}else{
		if(x1<p.x1){
			return true;
		}else{
			if(x2<p.x2){
				return true;
			}else{
				if(x2>p.x2){
					return false;
				}else{
					return false;
				}
			}
		}
	}
}

template <typename T_1,typename T_2>
const bool pair_c<T_1,T_2>::operator>=(const pair_c p)const{
	if(x1>p.x1){
		return true;
	}else{
		if(x1<p.x1){
			return false;
		}else{
			if(x2<p.x2){
				return false;
			}else{
				if(x2>p.x2){
					return true;
				}else{
					return true;
				}
			}
		}
	}
}

template <typename T_1,typename T_2>
const bool pair_c<T_1,T_2>::operator<=(const pair_c p)const{
	if(x1>p.x1){
		return false;
	}else{
		if(x1<p.x1){
			return true;
		}else{
			if(x2<p.x2){
				return true;
			}else{
				if(x2>p.x2){
					return false;
				}else{
					return true;
				}
			}
		}
	}
}

