//priority queue, small root heap
template <typename cactus>
class small_heap{
	private:
		int n;
		cactus c[MAXN];
	public:
		small_heap(void);
		void insert(const cactus v);
		const cactus top(void);
		const SIZE_C size(void);
		void pop(void);
		void clear(void);
		const bool empty(void);
};

template <typename cactus>
small_heap<cactus>::small_heap(void){
	n=0;
}

template <typename cactus>
void small_heap<cactus>::insert(const cactus v){
	n++;
	c[n]=v;
	int i=n;
	while(i!=1&&c[i]<c[i/2]){
		swap(c[i],c[i/2]);
		i/=2;
	}
}

template <typename cactus>
const cactus small_heap<cactus>::top(void){
	return c[1];
}

template <typename cactus>
const SIZE_C small_heap<cactus>::size(void){
	return n;
}

template <typename cactus>
void small_heap<cactus>::pop(void){
	int i=1;
	if(n==0)return;
	if(n==1){
		n--;
		return;
	}
	c[i]=c[n];
	n--;
	while(i*2<=n){
		if(i*2+1>n){
			if(c[i]>c[i*2]){
				swap(c[i],c[i*2]);
				i*=2;
			}else{
				return;
			}
		}else{
			if(c[i*2]<c[i*2+1]){
				if(c[i]>c[i*2]){
					swap(c[i],c[i*2]);
					i*=2;
				}else{
					return;
				}
			}else{
				if(c[i]>c[i*2+1]){
					swap(c[i],c[i*2+1]);
					i=i*2+1;
				}else{
					return;
				}
			}	
		}
	}
}

template <typename cactus>
void small_heap<cactus>::clear(void){
	n=0;
}

template <typename cactus>
const bool small_heap<cactus>::empty(void){
	return !(bool)n;
}



