#define DSU union_set
class union_set{//union find set
	private:
		int pre[MAXNUM+5];
		int height[MAXNUM+5];
	public:
		union_set(void);
		const int find(const int x);
		void merge(int x1,int x2);
		const bool relate(const int x1,const int x2);
		void clear(void);
};

union_set::union_set(void){
	for(int i=1;i<=MAXNUM-1;i++){
		pre[i]=i;
		height[i]=0;
	}
}

const int union_set::find(const int x){
	if(pre[x]!=x){
		pre[x]=find(pre[x]);
	}
	return pre[x];
}

void union_set::merge(int x1,int x2){
	x1=find(x1);
	x2=find(x2);
	if(height[x1]<height[x2]){
		pre[x1]=x2;
	}else{
		pre[x2]=x1;
	}
}

const bool union_set::relate(const int x1,const int x2){
	return find(x1)==find(x2);
}

void union_set::clear(void){
	for(int i=1;i<=MAXNUM;i++){
		pre[i]=i;
		height[i]=0;
	}
}

