const int lowbit(int x){//lowbit for tree array
	return x&(-x);
}

//tree array
template <typename cactus>
class tree_array{
	private:
		cactus tra[MAXN];
		int n;
	public:
		tree_array(void);
		tree_array(const int len);
		void clear(void);
		const SIZE_C size(void);
		void add(const cactus val,int pos);
		void add(int pos);
		const int sum(int pos);
		const cactus sum(const int pos1,const int pos2);
};

template <typename cactus>
tree_array<cactus>::tree_array(void){
	n=0;
}

template <typename cactus>
tree_array<cactus>::tree_array(const int len){
	n=len;
	for(int i=1;i<=n;i++){
		tra[i]=0;
	}
}

template <typename cactus>
void tree_array<cactus>::clear(void){
	for(int i=1;i<=n;i++){
		tra[i]=0;
	}
}

template <typename cactus>
const SIZE_C tree_array<cactus>::size(void){
	return n;
}

template <typename cactus>
void tree_array<cactus>::add(const cactus val,int pos){
	if(pos<1) return;
	while(pos<=n){
		tra[pos]+=val;
		pos+=lowbit(pos);
	}
}

template <typename cactus>
void tree_array<cactus>::add(int pos){
	if(pos<1) return;
	while(pos<=n){
		tra[pos]++;
		pos+=lowbit(pos);
	}
}

template <typename cactus>
const int tree_array<cactus>::sum(int pos){
	if(pos<1) return INF;
	cactus ret=0;
	while(pos>0){
		ret+=tra[pos];
		pos-=lowbit(pos);
	}
	return ret;
}

template <typename cactus>
const cactus tree_array<cactus>::sum(const int pos1,const int pos2){
	return sum(pos2)-sum(pos1-1);
}

