const bool inrange(int l,int r,int lx,int rx){
	//if [l,r] is contained in [lx,rx]
	return l>=lx&&r<=rx;
}

const bool outofrange(int l,int r,int lx,int rx){
	//if [l,r] is not contained in [lx,rx]
	return r<lx||l>rx;
}

template <typename cactus>
class max_seg_tree{//max segment tree
	private:
		cactus t[MAXN];
		cactus a[MAXN];
		int n;
		cactus tag[MAXN];
		void buildin(int l,int r,int p);
		void build(void);
		void maketag(int k,cactus v);
		void pushdown(int k);
		cactus query1(int k,int l,int r,int p);
		void change1(int k,int l,int r,int p,cactus v);
		cactus query(int k,int l,int r,int p1,int p2);
		void change(int k,int l,int r,int p1,int p2,cactus v);
	public:
		max_seg_tree(const int num);
		max_seg_tree(cactus *a1,cactus *a2);
		const cactus find(const int p);
		void add(const int p,const cactus val);
		const cactus max(const int l,const int r);
		void add(const int l,const int r,const cactus val);
		const SIZE_C size(void);
};

template <typename cactus>
void max_seg_tree<cactus>::buildin(int l,int r,int p){
	if(l==r){
		t[p]=a[l];
		return;
	}
	int mid=(l+r)>>1;
	p<<=1;
	buildin(l,mid,p);
	buildin(mid+1,r,p+1);
	t[p>>1]=((t[p]>t[p+1])?t[p]:t[p+1]);
}

template <typename cactus>
void max_seg_tree<cactus>::build(void){
	buildin(1,n,1);
}

template <typename cactus>
void max_seg_tree<cactus>::maketag(int k,cactus v){
	tag[k]+=v;
	t[k]+=v;
}

template <typename cactus>
void max_seg_tree<cactus>::pushdown(int k){
	maketag(k<<1,tag[k]);
	maketag((k<<1)+1,tag[k]);
	tag[k]=0;
}

template <typename cactus>
cactus max_seg_tree<cactus>::query1(int k,int l,int r,int p){
	if(l==r){
		return t[k];
	}else{
		int mid=(l+r)>>1;
		pushdown(k);
		if(p>mid){
			return query1((k<<1)+1,mid+1,r,p);
		}else{
			return query1(k<<1,l,mid,p);
		}
	}
}

template <typename cactus>
void max_seg_tree<cactus>::change1(int k,int l,int r,int p,cactus v){
	if(l==r){
		t[k]+=v;
		return;
	}else{
		int mid=(l+r)>>1;
		pushdown(k);
		if(p>mid){
			change1((k<<1)+1,mid+1,r,p,v);
		}else{
			change1(k<<1,l,mid,p,v);
		}
		t[k]=t[k<<1]>t[(k<<1)+1]?t[k<<1]:t[(k<<1)+1];
	}
}

template <typename cactus>
cactus max_seg_tree<cactus>::query(int k,int l,int r,int p1,int p2){
	if(inrange(l,r,p1,p2)){
		pushdown(k);
		return t[k];
	}
	if(outofrange(l,r,p1,p2)){
		return -INF;
	}else{
		int mid=(l+r)>>1;
		pushdown(k);
		cactus q1=query(k<<1,l,mid,p1,p2);
		cactus q2=query((k<<1)+1,mid+1,r,p1,p2);
		return q1>q2?q1:q2;
	}
}

template <typename cactus>
void max_seg_tree<cactus>::change(int k,int l,int r,int p1,int p2,cactus v){
	if(inrange(l,r,p1,p2)){
		maketag(k,v);
	}else{
		if(outofrange(l,r,p1,p2));
		else{
			pushdown(k);
			int mid=(l+r)>>1;
			change(k<<1,l,mid,p1,p2,v);
			change((k<<1)+1,mid+1,r,p1,p2,v);
			t[k]=t[k<<1]>t[(k<<1)+1]?t[k<<1]:t[(k<<1)+1];
		}
	}
}

template <typename cactus>
max_seg_tree<cactus>::max_seg_tree(const int num){
	n=num;
}

template <typename cactus>
max_seg_tree<cactus>::max_seg_tree(cactus *a1,cactus *a2){
	n=a2-a1;
	for(int i=1;i<=n;i++){
		a[i]=*a1;
		a1++;
		t[i]=0;
	}
	build();
}

template <typename cactus>
const cactus max_seg_tree<cactus>::find(const int p){
	return query1(1,1,n,p);
}

template <typename cactus>
void max_seg_tree<cactus>::add(const int p,const cactus val){
	change1(1,1,n,p,val);
}

template <typename cactus>
const cactus max_seg_tree<cactus>::max(const int l,const int r){
	return query(1,1,n,l,r);
}

template <typename cactus>
void max_seg_tree<cactus>::add(const int l,const int r,const cactus val){
	change(1,1,n,l,r,val);
}

template <typename cactus>
const SIZE_C max_seg_tree<cactus>::size(void){
	return n;
}



