template <typename cactus>
class max_st_list{//max st list
	private:
		int n,logn;
		int log2n[MAXN];
		cactus st[MAXN][35];
	public:
		explicit max_st_list(cactus *a1,cactus *a2);
		const cactus max(const int l,const int r);
};

template <typename cactus>
max_st_list<cactus>::max_st_list(cactus *a1,cactus *a2){
	log2n[0]=0;
	log2n[1]=0;
	n=a2-a1;
	for(int i=0;i<=n*2;i++){
		for(int j=0;j<35;j++){
			st[i][j]=-INF;
		}
	}
	st[1][0]=*a1;
	a1++;
	for(int i=2;i<=n;i++,a1++){
		st[i][0]=*a1;
		log2n[i]=log2n[i>>1]+1;
	}
	for(int j=1;(1<<j)<=n;j++){
		for(int i=1;i<=n;i++){
			st[i][j]=((st[i][j-1]>st[i+(1<<(j-1))][j-1])?st[i][j-1]:st[i+(1<<(j-1))][j-1]);
		}
	}
}

template <typename cactus>
const cactus max_st_list<cactus>::max(const int l,const int r){
	int l1=r-l+1;
	int k=log2n[l1];
	return st[l][k]>st[r-(1<<k)+1][k]?st[l][k]:st[r-(1<<k)+1][k];
}

