template <typename cactus>
class sum_segment_tree{
	private:
		int n;
		cactus tr[MAXN];
		cactus a[MAXN];
		cactus tag[MAXN];
		void buildin(int k,int l,int r);
		void build(void);
		void maketag(int k,cactus v,int l,int r);
		void pushdown(int k,int l,int r,int mid);
		const cactus query1(int k,int l,int r,int p);
		void change1(int k,int l,int r,int p,cactus v);
		const cactus query(int k,int l,int r,int pl,int pr);
		void change(int k,int l,int r,int pl,int pr,cactus v);
	public:
		sum_segment_tree(void);
		sum_segment_tree(const int num);
		sum_segment_tree(cactus *a1,cactus *a2);
		void add(const int p,const cactus val);
		void add(const int pl,const int pr,const cactus val);
		const cactus find(const int p);
		const cactus sum(const int pl,const int pr);
};

template <typename cactus>
void sum_segment_tree<cactus>::buildin(int k,int l,int r){
	tag[k]=0;
	if(l==r){
		tr[k]=a[l];
		return;
	}
	int mid=(l+r)>>1;
	buildin((k<<1),l,mid);
	buildin((k<<1)+1,mid+1,r);
	tr[k]=tr[k<<1]+tr[(k<<1)+1];
}

template <typename cactus>
void sum_segment_tree<cactus>::build(void){
	buildin(1,1,n);
}

template <typename cactus>
void sum_segment_tree<cactus>::maketag(int k,cactus v,int l,int r){
	tag[k]+=v;
	tr[k]+=v*(r-l+1);
}

template <typename cactus>
void sum_segment_tree<cactus>::pushdown(int k,int l,int r,int mid){
	if(!tag[k])return;
	maketag(k<<1,tag[k],l,mid);
	maketag((k<<1)+1,tag[k],mid+1,r);
	tag[k]=0;
}

template <typename cactus>
const cactus sum_segment_tree<cactus>::query1(int k,int l,int r,int p){
	if(l==r){
		return tr[k];
	}
	int mid=(l+r)>>1;
	pushdown(k,l,r,mid);
	if(p>mid){
		return query1((k<<1)+1,mid+1,r,p);
	}else{
		return query1(k<<1,l,mid,p);
	}
}

template <typename cactus>
void sum_segment_tree<cactus>::change1(int k,int l,int r,int p,cactus v){
	if(l==r){
		tr[k]+=v;
		return;
	}
	tr[k]+=v;
	int mid=(l+r)>>1;
	pushdown(k,l,r,mid);
	if(p>mid){
		change1((k<<1)+1,mid+1,r,p,v);
	}else{
		change1(k<<1,l,mid,p,v);
	}
}

template <typename cactus>
const cactus sum_segment_tree<cactus>::query(int k,int l,int r,int pl,int pr){
	if(inrange(l,r,pl,pr)){
		pushdown(k,l,r,(l+r)>>1);
		return tr[k];
	}
	if(outofrange(l,r,pl,pr)){
		return 0;
	}
	int mid=(l+r)>>1;
	pushdown(k,l,r,mid);
	return query(k<<1,l,mid,pl,pr)+query((k<<1)+1,mid+1,r,pl,pr);
}

template <typename cactus>
void sum_segment_tree<cactus>::change(int k,int l,int r,int pl,int pr,cactus v){
	if(inrange(l,r,pl,pr)){
		maketag(k,v,l,r);
		return;
	}
	if(outofrange(l,r,pl,pr)){
		return;
	}
	int mid=(l+r)>>1;
	pushdown(k,l,r,mid);
	change(k<<1,l,mid,pl,pr,v);
	change((k<<1)+1,mid+1,r,pl,pr,v);
	tr[k]=tr[k<<1]+tr[(k<<1)+1];
}

template <typename cactus>
sum_segment_tree<cactus>::sum_segment_tree(void){
	n=0;
}

template <typename cactus>
sum_segment_tree<cactus>::sum_segment_tree(const int num){
	n=num;
	for(int i=0;i<n*4+1;i++){
		tr[i]=0;
	}
}

template <typename cactus>
sum_segment_tree<cactus>::sum_segment_tree(cactus *a1,cactus *a2){
	n=a2-a1;
	for(int i=1;i<=n;i++){
		a[i]=*a1;
		a1++;
	}
	build();
}

template <typename cactus>
void sum_segment_tree<cactus>::add(const int p,const cactus val){
	change1(1,1,n,p,val);
}

template <typename cactus>
void sum_segment_tree<cactus>::add(const int pl,const int pr,const cactus val){
	change(1,1,n,pl,pr,val);
}

template <typename cactus>
const cactus sum_segment_tree<cactus>::find(const int p){
	return query1(1,1,n,p);
}

template <typename cactus>
const cactus sum_segment_tree<cactus>::sum(const int pl,const int pr){
	return query(1,1,n,pl,pr);
}

