		const cactus sum(const int pl,const int pr);
};

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
void segment_tree<cactus,f,chg>::buildin(int k,int l,int r){
	if(l==r){
		tr[k]=a[l];
		return;
	}
	int mid=(l+r)>>1;
	buildin((k<<1),l,mid);
	buildin((k<<1)+1,mid+1,r);
	tr[k]=f(tr[k<<1],tr[(k<<1)+1]);
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
void segment_tree<cactus,f,chg>::build(void){
	buildin(1,1,n);
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
const cactus segment_tree<cactus,f,chg>::query1(int k,int l,int r,int p){
	if(l==r){
		return tr[k];
	}
	int mid=(l+r)>>1;
	if(p>mid){
		return query1((k<<1)+1,mid+1,r,p);
	}else{
		return query1(k<<1,l,mid,p);
	}
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
void segment_tree<cactus,f,chg>::change1(int k,int l,int r,int p,cactus v,cactus (*chgf)(cactus,cactus)){
	if(l==r){
		tr[k]=chgf(tr[k],v);
		return;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		change1((k<<1)+1,mid+1,r,p,v,chgf);
	}else{
		change1(k<<1,l,mid,p,v,chgf);
	}
	tr[k]=f(tr[k<<1],tr[(k<<1)+1]);
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
const cactus segment_tree<cactus,f,chg>::query(int k,int l,int r,int pl,int pr){
	if(outofrange(l,r,pl,pr)){
		return 0;
	}
	if(l==r){
		return tr[k];
	}
	int mid=(l+r)>>1;
	return f(query(k<<1,l,mid,pl,pr),query((k<<1)+1,mid+1,r,pl,pr));
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
void segment_tree<cactus,f,chg>::change(int k,int l,int r,int pl,int pr,cactus v,cactus (*chgf)(cactus,cactus)){
	if(outofrange(l,r,pl,pr)){
		return;

	}
	if(l==r){
		tr[k]=chgf(tr[k],v);
		return;
	}
	int mid=(l+r)>>1;
	change(k<<1,l,mid,pl,pr,v,chgf);
	change((k<<1)+1,mid+1,r,pl,pr,v,chgf);
	tr[k]=f(tr[k<<1],tr[(k<<1)+1]);
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
segment_tree<cactus,f,chg>::segment_tree(void){
	n=0;
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
segment_tree<cactus,f,chg>::segment_tree(const int num){
	n=num;
	for(int i=0;i<n*4+1;i++){
		tr[i]=0;
	}
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
segment_tree<cactus,f,chg>::segment_tree(cactus *a1,cactus *a2){
	n=a2-a1;
	for(int i=1;i<=n;i++){
		a[i]=*a1;
		a1++;
	}
	build();
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
void segment_tree<cactus,f,chg>::add(const int p,const cactus val,cactus (*change_fx)(cactus,cactus)){
	change1(1,1,n,p,val,change_fx);
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
void segment_tree<cactus,f,chg>::add(const int pl,const int pr,const cactus val,cactus (*change_fx)(cactus,cactus)){
	change(1,1,n,pl,pr,val,change_fx);
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
const cactus segment_tree<cactus,f,chg>::find(const int p){
	return query1(1,1,n,p);
}

template <typename cactus,cactus (*f)(cactus,cactus),cactus (*chg)(cactus,cactus)>
const cactus segment_tree<cactus,f,chg>::sum(const int pl,const int pr){
	return query(1,1,n,pl,pr);
}

