template <typename cactus>
void splay<cactus>::resize(const int p){
	tr[p].size=1;
	if(tr[p].left!=-1){
		tr[p].size+=tr[tr[p].left].size;
	}
	if(tr[p].right!=-1){
		tr[p].size+=tr[tr[p].right].size;
	}
}

template <typename cactus>
const bool splay<cactus>::lrson(const int p){
	return tr[tr[p].p].right==p;
}

template <typename cactus>
void splay<cactus>::release_empty(const int p){
	n--;
	if(p==n){
		return;
	}
	if(n==root){
		root=p;
	}
	tr[p].size=tr[n].size;
	tr[p].v=tr[n].v;
	tr[p].left=tr[n].left;
	tr[p].right=tr[n].right;
	tr[p].p=tr[n].p;
	if(tr[p].right!=-1){
		tr[tr[p].right].p=p;
	}
	if(tr[p].left!=-1){
		tr[tr[p].left].p=p;
	}
	if(tr[p].p!=-1){
		if(lrson(n)){
			tr[tr[p].p].right=p;
		}else{
			tr[tr[p].p].left=p;
		}
	}
}

template <typename cactus>
void splay<cactus>::left_rotate(const int p){
	int pa=tr[p].p;
	int rght=tr[p].right;
	int rl=tr[rght].left;

	if(p==root){
		root=rght;
		tr[rght].p=-1;
	}else{
		if(lrson(p)){
			tr[pa].right=rght;
			tr[rght].p=pa;
		}else{
			tr[pa].left=rght;
			tr[rght].p=pa;
		}
	}

	tr[p].right=rl;
	tr[rl].p=p;

	tr[rght].left=p;
	tr[p].p=rght;
	resize(p);
	resize(rght);
}

template <typename cactus>
void splay<cactus>::right_rotate(const int p){
	int pa=tr[p].p;
	int lft=tr[p].left;
	int lr=tr[lft].right;

	if(p==root){
		tr[lft].p=-1;
		root=lft;
	}else{
		if(lrson(p)){
			tr[pa].right=lft;
			tr[lft].p=pa;
		}else{
			tr[pa].left=lft;
			tr[lft].p=pa;
		}
	}

	tr[p].left=lr;
	tr[lr].p=p;

	tr[lft].right=p;
	tr[p].p=lft;
	resize(p);
	resize(lft);
}

template <typename cactus>
void splay<cactus>::zig(const int p){
	right_rotate(tr[p].p);
}

template <typename cactus>
void splay<cactus>::zag(const int p){
	left_rotate(tr[p].p);
}

template <typename cactus>
void splay<cactus>::rotate_to(const int p,const int dtn){
	while(tr[p].p!=dtn){
		if(lrson(p)){
			zag(p);
		}else{
			zig(p);
		}
	}
}

template <typename cactus>
bool splay<cactus>::get_node(const int p,const cactus v){//fail 0, succeed 1
	if(p==-1){
		return 0;
	}
	if(v==tr[p].v){
		rotate_to(p);
		return 1;
	}else{
		if(v>tr[p].v){
			return get_node(tr[p].right,v);
		}else{
			return get_node(tr[p].left,v);
		}
	}
}

template <typename cactus>
const int splay<cactus>::get_root_rank(void){
	if(tr[root].left==-1){
		return 1;
	}else{
		return tr[tr[root].left].size+1;
	}
}

template <typename cactus>
const int splay<cactus>::get_max(const int p){
	if(p==-1){
		return -1;
	}
	else{
		if(tr[p].right==-1){
			return p;
		}else{
			return get_max(tr[p].right);
		}
	}
}

template <typename cactus>
const int splay<cactus>::get_min(const int p){
	if(p==-1){
		return -1;
	}
	else{
		if(tr[p].left==-1){
			return p;
		}else{
			return get_min(tr[p].left);
		}
	}
}

template <typename cactus>
const cactus splay<cactus>::get_max_v(const int p){
	if(p==-1){
		return INF;
	}
	else{
		if(tr[p].right==-1){
			return tr[p].v;
		}else{
			return get_max_v(tr[p].right);
		}
	}
}

template <typename cactus>
const cactus splay<cactus>::get_min_v(const int p){
	if(p==-1){
		return INF;
	}
	else{
		if(tr[p].left==-1){
			return tr[p].v;
		}else{
			return get_min_v(tr[p].left);
		}
	}
}

template <typename cactus>
const bool splay<cactus>::find_in(const cactus v){
	if(n==0){
		return 0;
	}
	return get_node(root,v);
}

template <typename cactus>
const int splay<cactus>::rank_in(const cactus v){
	if(n==0){
		return INF;
	}
	if(get_node(root,v)){
		return get_root_rank();
	}else{
		return INF;
	}
}

template <typename cactus>
const cactus splay<cactus>::pre_in(const cactus v){
	int pos=root;
	cactus res=INF;
	while(pos!=-1){
		if(v>tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].right;
		}else{
			pos=tr[pos].left;
		}
	}
	get_node(root,res);
	return res;
}

template <typename cactus>
const cactus splay<cactus>::suc_in(const cactus v){
	int pos=root;
	cactus res=-INF;
	while(pos!=-1){
		if(v<tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].left;
		}else{
			pos=tr[pos].right;
		}
	}
	get_node(root,res);
	return res;
}

template <typename cactus>
void splay<cactus>::delete_in(const cactus v){
	if(n==0){
		return;
	}
	if(!get_node(root,v)){
		return;
	}
	cactus pre=get_max(tr[root].left);
	cactus suc=get_min(tr[root].right);
	int pt=root;
	if(pre==-1){
		if(suc==-1){
			n--;
			return;
		}else{
			rotate_to(suc);
			tr[suc].left=-1;
			release_empty(pt);
			tr[suc].size--;
		}
	}else{
		if(suc==-1){
			rotate_to(pre);
			tr[pre].right=-1;
			release_empty(pt);
			tr[pre].size--;
		}else{
			rotate_to(pre);
			rotate_to(suc,pre);
			tr[suc].left=-1;
			release_empty(pt);
			tr[pre].size--;
			tr[suc].size--;
		}
	}
}

template <typename cactus>
void splay<cactus>::insert_in(const cactus v){
	if(n==0){
		tr[n]=splay_node <cactus> (-1,-1,v,-1,1);
		root=0;
		n++;
		return;
	}
	if(get_node(root,v)){
		return;
	}else{
		int np=root;
		while(1){
			tr[np].size++;
			if(v>tr[np].v){
				if(tr[np].right==-1){
					tr[n]=splay_node <cactus> (-1,-1,v,np,1);
					tr[np].right=n;
					rotate_to(n);
					n++;
					return;
				}else{
					np=tr[np].right;
					continue;
				}
			}else{
				if(tr[np].left==-1){
					tr[n]=splay_node <cactus> (-1,-1,v,np,1);
					tr[np].left=n;
					rotate_to(n);
					n++;
					return;
				}else{
					np=tr[np].left;
					continue;
				}
			}
		}
	}
}

template <typename cactus>
const cactus splay<cactus>::kth_in_root(const int rootx,const int kth){
	if(tr[rootx].size==1){
		rotate_to(rootx);
		return tr[rootx].v;
	}
	if(tr[rootx].left==-1){
		if(kth==1){
			return tr[rootx].v;
		}
		return kth_in_root(tr[rootx].right,kth-1);
	}else{
		if(kth>tr[tr[rootx].left].size+1){
			return kth_in_root(tr[rootx].right,kth-tr[tr[rootx].left].size-1);
		}else{
			if(kth==tr[tr[rootx].left].size+1){
				rotate_to(rootx);
				return tr[rootx].v;
			}else{
				return kth_in_root(tr[rootx].left,kth);
			}
		}
	}
}

template <typename cactus>
const cactus splay<cactus>::kth_in(const int kth){
	if(n==0||kth<1||kth>n){
		return INF;
	}
	return kth_in_root(root,kth);
}

template <typename cactus>
const cactus splay<cactus>::max_in(void){
	if(n==0){
		return INF;
	}
	int np=root;
	while(tr[np].right!=-1){
		np=tr[np].right;
	}
	return tr[np].v;
}

template <typename cactus>
const cactus splay<cactus>::min_in(void){
	if(n==0){
		return INF;
	}
	int np=root;
	while(tr[np].left!=-1){
		np=tr[np].left;
	}
	return tr[np].v;
}

