}

template <typename cactus>
void multi_splay<cactus>::release_empty(const int p){
	n--;
	if(p==n){
		return;
	}
	if(root==n){
		root=p;
	}
	tr[p]=tr[n];
	if(tr[p].right!=-1){
		tr[tr[p].right].p=p;
	}
	if(tr[p].left!=-1){
		tr[tr[p].left].p=p;
	}
	if(tr[p].p!=-1){
		if(lrson(n)){
			tr[tr[p].p].right=p;
		}else{
			tr[tr[p].p].left=p;
		}
	}
}

template <typename cactus>
void multi_splay<cactus>::left_rotate(const int p){
	int pa=tr[p].p;
	int rght=tr[p].right;
	int rl=tr[rght].left;

	if(p==root){
		root=rght;
		tr[rght].p=-1;
	}else{
		if(lrson(p)){
			tr[pa].right=rght;
			tr[rght].p=pa;
		}else{
			tr[pa].left=rght;
			tr[rght].p=pa;
		}
	}

	tr[p].right=rl;
	tr[rl].p=p;

	tr[rght].left=p;
	tr[p].p=rght;

	resize(p);
	resize(rght);
}

template <typename cactus>
void multi_splay<cactus>::right_rotate(const int p){
	int pa=tr[p].p;
	int lft=tr[p].left;
	int lr=tr[lft].right;

	if(p==root){
		tr[lft].p=-1;
		root=lft;
	}else{
		if(lrson(p)){
			tr[pa].right=lft;
			tr[lft].p=pa;
		}else{
			tr[pa].left=lft;
			tr[lft].p=pa;
		}
	}

	tr[p].left=lr;
	tr[lr].p=p;

	tr[lft].right=p;
	tr[p].p=lft;

	resize(p);
	resize(p);
}

template <typename cactus>
void multi_splay<cactus>::zig(const int p){
	right_rotate(tr[p].p);
}

template <typename cactus>
void multi_splay<cactus>::zag(const int p){
	left_rotate(tr[p].p);
}

template <typename cactus>
void multi_splay<cactus>::rotate_to(const int p,const int dtn){
	while(tr[p].p!=dtn){
		if(lrson(p)){
			zag(p);
		}else{
			zig(p);
		}
	}
}

template <typename cactus>
bool multi_splay<cactus>::get_node(const int p,const cactus v){//fail 0, succeed 1
	if(p==-1){
		return 0;
	}
	if(v==tr[p].v){
		rotate_to(p);
		return 1;
	}else{
		if(v>tr[p].v){
			return get_node(tr[p].right,v);
		}else{
			return get_node(tr[p].left,v);
		}
	}
}

template <typename cactus>
const int multi_splay<cactus>::get_root_rank(void){
	if(tr[root].left==-1){
		return 1;
	}else{
		return tr[tr[root].left].size+1;
	}
}

template <typename cactus>
const int multi_splay<cactus>::get_max(const int p){
	if(p==-1){
		return -1;
	}
	else{
		if(tr[p].right==-1){
			return p;
		}else{
			return get_max(tr[p].right);
		}
	}
}

template <typename cactus>
const int multi_splay<cactus>::get_min(const int p){
	if(p==-1){
		return -1;
	}
	else{
		if(tr[p].left==-1){
			return p;
		}else{
			return get_min(tr[p].left);
		}
	}
}

