template <typename cactus>
const bool multi_splay<cactus>::find_in(const cactus v){
	if(n==0){
		return 0;
	}
	return get_node(root,v);
}

template <typename cactus>
const int multi_splay<cactus>::rank_in(const cactus v){
	if(n==0){
