	if(get_node(root,v)){
		return get_root_rank();
	}else{
		return INF;
	}
}

template <typename cactus>
const cactus multi_splay<cactus>::pre_in(const cactus v){
	int pos=root;
	cactus res=-INF;
	while(pos!=-1){
		if(v>tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].right;
		}else{
			pos=tr[pos].left;
		}
	}
	get_node(root,res);
	return res;
}

template <typename cactus>
const cactus multi_splay<cactus>::suc_in(const cactus v){
	int pos=root;
	cactus res=INF;
	while(pos!=-1){
		if(v<tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].left;
		}else{
			pos=tr[pos].right;
		}
	}
	get_node(root,res);
	return res;
}

template <typename cactus>
void multi_splay<cactus>::delete_in(const cactus v){
	if(n==0){
		return;
	}
	if(!get_node(root,v)){
		return;
	}
	if(tr[root].cnt>1){
		tr[root].cnt--;
		tr[root].size--;
		return;
	}
	int pre=get_max(tr[root].left);
	int suc=get_min(tr[root].right);
	int pt=root;
	if(pre==-1){
		if(suc==-1){
			n--;
			return;
		}else{
			rotate_to(suc);
			tr[suc].left=-1;
			release_empty(pt);
			tr[suc].size--;
		}
	}else{
		if(suc==-1){
			rotate_to(pre);
			tr[pre].right=-1;
			release_empty(pt);
			tr[pre].size--;
		}else{
			rotate_to(pre);
			rotate_to(suc,pre);
			tr[suc].left=-1;
			release_empty(pt);
			tr[pre].size--;
			tr[suc].size--;
		}
	}
}

template <typename cactus>
void multi_splay<cactus>::insert_in(const cactus v){
	if(n==0){
		tr[n]=multi_splay_node <cactus> (-1,-1,v,-1,1,1);
		root=0;
		n++;
		return;
	}
	if(get_node(root,v)){
		tr[root].cnt++;
		tr[root].size++;
		return;
	}else{
		int np=root;
		while(1){
			tr[np].size++;
			if(v>tr[np].v){
				if(tr[np].right==-1){
					tr[n]=multi_splay_node <cactus> (-1,-1,v,np,1,1);
					tr[np].right=n;
					rotate_to(n);
					n++;
					return;
				}else{
					np=tr[np].right;
					continue;
				}
			}else{
				if(tr[np].left==-1){
					tr[n]=multi_splay_node <cactus> (-1,-1,v,np,1,1);
					tr[np].left=n;
					rotate_to(n);
					n++;
					return;
				}else{
					np=tr[np].left;
					continue;
				}
			}
		}
	}
}

template <typename cactus>
const cactus multi_splay<cactus>::kth_in_root(const int rootx,const int kth){
	if(tr[rootx].left==-1){
		if(kth<=tr[rootx].cnt){
			return tr[rootx].v;
		}
		return kth_in_root(tr[rootx].right,kth-tr[rootx].cnt);
	}else{
		if(kth>tr[tr[rootx].left].size+tr[rootx].cnt){
			return kth_in_root(tr[rootx].right,kth-tr[tr[rootx].left].size-tr[rootx].cnt);
		}else{
			if(kth<=tr[tr[rootx].left].size){
				return kth_in_root(tr[rootx].left,kth);
			}else{
				return tr[rootx].v;
			}
		}
	}
}

template <typename cactus>
const cactus multi_splay<cactus>::kth_in(const int kth){
	if(n==0||kth<1||kth>tr[root].size){
		return INF;
	}
	return kth_in_root(root,kth);
}

template <typename cactus>
const cactus multi_splay<cactus>::max_in(void){
	if(n==0){
		return INF;
	}
	int np=root;
	while(tr[np].right!=-1){
		np=tr[np].right;
	}
	return tr[np].v;
}

