int weighed_tree::new_node(int l,int r,int v){
	tr[n]=weighed_node(l,r,v);
	n++;
	return n-1;
}

void weighed_tree::buildin(int k,int l,int r){
	if(l==r){
		return;
	}
	int mid=(l+r)>>1;
	tr[k].left=new_node(-1,-1,0);
	tr[k].right=new_node(-1,-1,0);
	buildin(tr[k].left,l,mid);
	buildin(tr[k].right,mid+1,r);
}

void weighed_tree::build(void){
	tr[0]=weighed_node();
	n=1;
	buildin(0,1,val);
}

void weighed_tree::init(const int value){
	val=value;
	n=0;
	build();
}

void weighed_tree::init(void){
	val=MAXNUM;
	n=0;
	build();
}

void weighed_tree::point_add_in(int k,int l,int r,int v,int cnt){
	if(l==r){
		tr[k].v+=cnt;
		if(tr[k].v<0){
			tr[k].v=0;
		}
		return;
	}
	int mid=(l+r)>>1;
	if(v>mid){
		point_add_in(tr[k].right,mid+1,r,v,cnt);
	}else{
		point_add_in(tr[k].left,l,mid,v,cnt);
	}
	tr[k].v=tr[tr[k].left].v+tr[tr[k].right].v;
}

void weighed_tree::point_add(int v,int cnt){
	point_add_in(0,1,val,v,cnt);
}

const int weighed_tree::point_query_in(int k,int l,int r,int v){
	if(l==r){
		return tr[k].v;
	}
	int mid=(l+r)>>1;
	if(v>mid){
		return point_query_in(tr[k].right,mid+1,r,v);
	}else{
		return point_query_in(tr[k].left,l,mid,v);
	}
}

const int weighed_tree::point_query(int v){
	return point_query_in(0,1,val,v);
}

const int weighed_tree::range_query_in(int k,int l,int r,int vl,int vr){
	if(inrange(l,r,vl,vr)){
		return tr[k].v;
	}
	if(outofrange(l,r,vl,vr)){
		return 0;
	}
	int mid=(l+r)>>1;
	return range_query_in(tr[k].left,l,mid,vl,vr)+range_query_in(tr[k].right,mid+1,r,vl,vr);
}

const int weighed_tree::range_query(int vl,int vr){
	return range_query_in(0,1,val,vl,vr);
}

const int weighed_tree::kth_in_root(int rootx,int l,int r,int kth){
	if(l==r){
		return l;
	}
	int mid=(l+r)>>1;
	if(kth>tr[tr[rootx].left].v){
		return kth_in_root(tr[rootx].right,mid+1,r,kth-tr[tr[rootx].left].v);
	}else{
		return kth_in_root(tr[rootx].left,l,mid,kth);
	}
}

void weighed_tree::insert_in(const int v){
	point_add(v,1);
}

void weighed_tree::multi_insert_in(const int v,const int cnt){
	point_add(v,cnt);
}

