	return (bool)point_query(v);
}

const int weighed_tree::rank_in(const int v){
	if(v==1){
		return 1;
	}
	return count_in(1,v-1)+1;
}

const int weighed_tree::kth_in(const int kth){
	return kth_in_root(0,1,val,kth);
}

void weighed_tree::add_in(const int v,const int add_value){
	point_add(v,-1);
	point_add(v+add_value,1);
}

void weighed_tree::multi_add_in(const int v,const int add_value,const int cnt){
	point_add(v,-cnt);
	point_add(v+add_value,cnt);
}

void weighed_tree::minus_in(const int v,const int minus_value){
	point_add(v,-1);
	point_add(v-minus_value,1);
}

void weighed_tree::multi_minus_in(const int v,const int minus_value,const int cnt){
	point_add(v,-cnt);
	point_add(v-minus_value,cnt);
}

void weighed_tree::merge_in(const weighed_tree& w_tr){
	if(val!=w_tr.val){
		return;
	}
	for(int i=0;i<n;i++){
		tr[i].v+=w_tr.tr[i].v;
	}
}

void weighed_tree::anti_merge_in(const weighed_tree& w_tr){
	if(val!=w_tr.val){
		return;
	}
	for(int i=0;i<n;i++){
		tr[i].v-=w_tr.tr[i].v;
	}
}

