const int president_tree::new_node(void){
	tr[n]=president_node(-1,-1,0);
	n++;
	return n-1;
}

const int president_tree::new_node(int l,int r,int v){
	tr[n]=president_node(l,r,v);
	n++;
	return n-1;
}

void president_tree::buildin(int k,int l,int r){
	if(l==r){
		return;
	}
	tr[k].left=new_node();
	tr[k].right=new_node();
	int mid=(l+r)>>1;
	buildin(tr[k].left,l,mid);
	buildin(tr[k].right,mid+1,r);
}

void president_tree::build(void){
	r=1;
	root[0]=0;
	n=1;
	tr[0]=president_node();
	buildin(0,1,val);
}

void president_tree::init(void){
	val=MAXNUM;
	build();
}

