	val=vrange;
	build();
}

const int president_tree::point_query_in(int k,int l,int r,int v){
	if(l==r){
		return tr[k].v;
	}
	int mid=(l+r)>>1;
	if(v>mid){
		return point_query_in(tr[k].right,mid+1,r,v);
	}else{
		return point_query_in(tr[k].left,l,mid,v);
	}
}

const int president_tree::point_query(int version,int v){
	return point_query_in(root[version],1,val,v);
}

const int president_tree::range_query_in(int k,int l,int r,int vl,int vr){
	if(inrange(l,r,vl,vr)){
		return tr[k].v;
	}
	if(outofrange(l,r,vl,vr)){
		return 0;
	}
	int mid=(l+r)>>1;
	return range_query_in(tr[k].left,l,mid,vl,vr)+range_query_in(tr[k].right,mid+1,r,vl,vr);
}

const int president_tree::range_query(int version,int vl,int vr){
	return range_query_in(root[version],1,val,vl,vr);
}

void president_tree::build_linear_in(const int pre_pt,const int k,const int l,const int r,const int p,const int v){
	if(l==r){
		tr[k].v=tr[pre_pt].v+v;
		if(tr[k].v<0){
			tr[k].v=0;
		}
		n++;
		return;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		tr[k].left=tr[pre_pt].left;
		tr[k].right=n+1;
		n++;
		build_linear_in(tr[pre_pt].right,n,mid+1,r,p,v);
		tr[k].v=tr[tr[k].left].v+tr[tr[k].right].v;
		return;
	}else{
		tr[k].right=tr[pre_pt].right;
		tr[k].left=n+1;
		n++;
		build_linear_in(tr[pre_pt].left,n,l,mid,p,v);
		tr[k].v=tr[tr[k].left].v+tr[tr[k].right].v;
		return;
	}
}

void president_tree::build_linear(const int pre_root,const int p,const int v){
	build_linear_in(pre_root,n,1,val,p,v);
}

void president_tree::build_new(const int pre_root,const int p,const int v){
	root[r]=n;
	r++;
	build_linear(pre_root,p,v);
}

void president_tree::insert_on_pre_root(const int pre_root,const int v,const int cnt){
	build_new(pre_root,v,cnt);
}

const int president_tree::kth_in_root(int rootx,int l,int r,int kth){
	if(l==r){
		return l;
	}
	int mid=(l+r)>>1;
	if(kth>tr[tr[rootx].left].v){
		return kth_in_root(tr[rootx].right,mid+1,r,kth-tr[tr[rootx].left].v);
	}else{
		return kth_in_root(tr[rootx].left,l,mid,kth);
	}
}

const int president_tree::kth_of_root_in(const int root,const int kth){
	return kth_in_root(root,1,val,kth);
}

