const int range_weighed_query_tree::new_node(void){
	n++;
	return n-1;
}

const int range_weighed_query_tree::new_node(int l,int r,int v){
	tr[n]=range_seg_node(l,r,v);
	n++;
	return n-1;
}

void range_weighed_query_tree::buildin(int k,int l,int r){
	if(l==r){
		return;
	}
	tr[k].left=new_node();
	tr[k].right=new_node();
	int mid=(l+r)>>1;
	buildin(tr[k].left,l,mid);
	buildin(tr[k].right,mid+1,r);
}

void range_weighed_query_tree::build(void){
	r=1;
	n=1;
	root[0]=0;
	buildin(0,1,val);
}

void range_weighed_query_tree::build_new(int pre_node,int k,int l,int r,int v){
	if(l==r){
		tr[k].v=tr[pre_node].v+1;
		return;
	}
	tr[k].v=tr[pre_node].v+1;
	int mid=(l+r)>>1;
	if(v>mid){
		tr[k].left=tr[pre_node].left;
		tr[k].right=new_node();
		build_new(tr[pre_node].right,tr[k].right,mid+1,r,v);
		return;
	}else{
		tr[k].right=tr[pre_node].right;
		tr[k].left=new_node();
		build_new(tr[pre_node].left,tr[k].left,l,mid,v);
		return;
	}
}

void range_weighed_query_tree::init(int *pl,int *pr){
	val=10;
	for(int *x=pl;x<pr;x++){
		val=val>*x?val:*x;
	}
	build();
	for(;pl<pr;pl++){
		root[r]=new_node();
		build_new(root[r-1],n-1,1,val,*pl);
		r++;
	}
}

int range_weighed_query_tree::point_query(int k,int l,int r,int v){
	if(l==r){
		return tr[k].v;
	}
	int mid=(l+r)>>1;
	if(v>mid){
		return point_query(tr[k].right,mid+1,r,v);
	}else{
		return point_query(tr[k].left,l,mid,v);
	}
}

int range_weighed_query_tree::range_query(int k,int l,int r,int vl,int vr){
	if(inrange(l,r,vl,vr)){
		return tr[k].v;
	}
	if(outofrange(l,r,vl,vr)){
		return 0;
	}
	int mid=(l+r)>>1;
	return range_query(tr[k].left,l,mid,vl,vr)+range_query(tr[k].right,mid+1,r,vl,vr);
}

int range_weighed_query_tree::kth_value(int root,int l,int r,int kth){
	if(l==r){
		return l;
	}
	int mid=(l+r)>>1;
	if(kth>tr[tr[root].left].v){
		return kth_value(tr[root].right,mid+1,r,kth-tr[tr[root].left].v);
	}else{
		return kth_value(tr[root].left,l,mid,kth);
	}
}

int range_weighed_query_tree::v_rank(int root,int v){
	if(v==1){
		return 1;
	}
	return range_query(root,1,val,1,v-1)+1;
}

bool range_weighed_query_tree::find_exist(int root,int v){
