}

const int range_weighed_query_tree::get_sum_value_in(int k1,int k2,int l,int r,int v){
	if(l==r){
		return tr[k2].v-tr[k1].v;
	}
	int mid=(l+r)>>1;
	if(v>mid){
		return get_sum_value_in(tr[k1].right,tr[k2].right,mid+1,r,v);
	}else{
		return get_sum_value_in(tr[k1].left,tr[k2].left,l,mid,v);
	}
}

const int range_weighed_query_tree::get_sum_value(const int pl,const int pr,int v){
	if(pl==1){
		return point_query(root[pr],1,val,v);
	}else{
		return get_sum_value_in(root[pl-1],root[pr],1,val,v);
	}
}

const int range_weighed_query_tree::get_sum_range_in(int k1,int k2,int l,int r,int vl,int vr){
	if(inrange(l,r,vl,vr)){
		return tr[k2].v-tr[k1].v;
	}
	if(outofrange(l,r,vl,vr)){
		return 0;
	}
	int mid=(l+r)>>1;
	return get_sum_range_in(tr[k1].left,tr[k2].left,l,mid,vl,vr)+get_sum_range_in(tr[k1].right,tr[k2].right,mid+1,r,vl,vr);
}

const int range_weighed_query_tree::get_sum_range(const int vl,const int vr,const int pl,const int pr){
	if(vl==1){
		return range_query(root[pr],1,val,vl,vr);
	}
	return get_sum_range_in(root[pl-1],root[pr],1,val,vl,vr);
}

const int range_weighed_query_tree::range_rank_in(int pl,int pr,int v){
	if(v==1){
		return 1;
	}
	return get_sum_range(1,v-1,pl,pr);
}

const int range_weighed_query_tree::range_kth_inline(int k1,int k2,int l,int r,int kth){
	if(l==r){
		return l;
	}
	int mid=(l+r)>>1;
	if(kth>tr[tr[k2].left].v-tr[tr[k1].left].v){
		return range_kth_inline(tr[k1].right,tr[k2].right,mid+1,r,kth-tr[tr[k2].left].v+tr[tr[k1].left].v);
	}else{
		return range_kth_inline(tr[k1].left,tr[k2].left,l,mid,kth);
	}
}

const int range_weighed_query_tree::range_kth_in(int pl,int pr,int kth){
	if(pl==1){
		return kth_value(root[pr],1,val,kth);
	}
	return range_kth_inline(root[pl-1],root[pr],1,val,kth);
}

const bool range_weighed_query_tree::find_in(int pl,int pr,int v){
	return (bool)get_sum_value(pl,pr,v);
}

