class discrete_range_weighed_query_tree{
	private:
		pair_c <int,int> a[MAXN];
		int ax[MAXN];
		int d[MAXN];//disctete
		int n;
		range_weighed_query_tree t=range_weighed_query_tree(d+1,d+5+1);
	public:
		//note that numbers begin from 1
		explicit discrete_range_weighed_query_tree(int *a1,int *a2);
		const SIZE_C value_range(void);
		const bool find(const int range_l,const int range_r,const int v);
		const int count(const int range_l,const int range_r,const int v);
		const int count(const int range_l,const int range_r,const int vl,const int vr);
		const bool rank(const int range_l,const int range_r,const int v);
		const int kth(const int range_l,const int range_r,const int k);
};

discrete_range_weighed_query_tree::discrete_range_weighed_query_tree(int *a1,int *a2){
	int *x=a1;
	for(n=0;x<a2;x++){
		a[n]=pair_c <int,int> (*x,n);
		n++;
	}
	sort(a,a+n);
	d[1]=a[0].x1;
	ax[a[0].x2]=1;
	for(int i=1,j=1;i<n;i++){
		if(a[i].x1!=a[i-1].x1){
			j++;
			d[j]=a[i].x1;
		}
		ax[a[i].x2]=j;
	}
	t=range_weighed_query_tree(ax,ax+n);
}

const SIZE_C discrete_range_weighed_query_tree::value_range(void){
	return t.value_range();
}

const bool discrete_range_weighed_query_tree::find(const int range_l,const int range_r,const int v){
	return d[t.find(range_l,range_r,v)];
}

const int discrete_range_weighed_query_tree::count(const int range_l,const int range_r,const int v){
	return d[t.count(range_l,range_r,v)];
}

const int discrete_range_weighed_query_tree::count(const int range_l,const int range_r,const int vl,const int vr){
