template <typename cactus>
inline const int treap<cactus>::rand_c(void){
    return seed=(int)((seed*4827153LL+114514)%2147483647);
}

template <typename cactus>
void treap<cactus>::resize(const int p){
	tr[p].size=1+tr[tr[p].left].size+tr[tr[p].right].size;
}

template <typename cactus>
void treap<cactus>::release_empty(const int p){
	if(p==n){
		n--;
		return;
	}
	tr[p].size=tr[n].size;
	tr[p].v=tr[n].v;
	tr[p].left=tr[n].left;
	tr[p].right=tr[n].right;
	tr[p].p=tr[n].p;
	tr[p].priority=tr[n].priority;
	if(tr[p].right!=0){
		tr[tr[p].right].p=p;
	}
	if(tr[p].left!=0){
		tr[tr[p].left].p=p;
	}
	if(tr[p].p!=0){
		if(lrson(n)){
			tr[tr[p].p].right=p;
		}else{
			tr[tr[p].p].left=p;
		}
	}else{
		root=p;
	}
	n--;
}

template <typename cactus>
const bool treap<cactus>::lrson(const int p){
	return p==tr[tr[p].p].right;
}

template <typename cactus>
void treap<cactus>::left_rotate(const int p){
	const int rp=tr[p].right;
	const int pa=tr[p].p;
	const int rl=tr[tr[p].right].left;

	if(p==root){
		root=rp;
		tr[rp].p=0;
	}else{
		if(lrson(p)){
			tr[pa].right=rp;
			tr[rp].p=pa;
		}else{
			tr[pa].left=rp;
			tr[rp].p=pa;
		}
	}

	tr[p].p=rp;
	tr[rp].left=p;

	tr[p].right=rl;
	tr[rl].p=p;

	resize(p);
	resize(rp);

	tr[0].p=0;
	tr[0].left=0;
	tr[0].right=0;
}

template <typename cactus>
void treap<cactus>::right_rotate(const int p){
	const int lp=tr[p].left;
	const int pa=tr[p].p;
	const int lr=tr[tr[p].left].right;

	if(p==root){
		root=lp;
		tr[lp].p=0;
	}else{
		if(lrson(p)){
			tr[pa].right=lp;
			tr[lp].p=pa;
		}else{
			tr[pa].left=lp;
			tr[lp].p=pa;
		}
	}

	tr[p].p=lp;
	tr[lp].right=p;

	tr[p].left=lr;
	tr[lr].p=p;

	resize(p);
	resize(lp);

	tr[0].p=0;
	tr[0].left=0;
	tr[0].right=0;
}

template <typename cactus>
void treap<cactus>::zig(const int p){
	right_rotate(tr[p].p);
}

template <typename cactus>
void treap<cactus>::zag(const int p){
	left_rotate(tr[p].p);
}

template <typename cactus>
const int treap<cactus>::find_or_get_p(const cactus v){//returns 0-pos if found and parent if not
	int pos=root;
	while(1){
		if(tr[pos].v>v){
			if(tr[pos].left==0){
				return pos;
			}else{
				pos=tr[pos].left;
				continue;
			}
		}else{
			if(tr[pos].v<v){
				if(tr[pos].right==0){
					return pos;
				}else{
					pos=tr[pos].right;
					continue;
				}
			}else{
				return -pos;
			}
		}
	}
}

template <typename cactus>
const cactus treap<cactus>::get_max_in(const int p){
	if(tr[p].right==0){
		return tr[p].v;
	}
	return get_max_in(tr[p].right);
}

template <typename cactus>
const cactus treap<cactus>::get_min_in(const int p){
	if(tr[p].left==0){
		return tr[p].v;
	}
	return get_min_in(tr[p].left);
}

template <typename cactus>
const cactus treap<cactus>::max_in(void){
	return get_max_in(root);
}

template <typename cactus>
const cactus treap<cactus>::min_in(void){
	return get_min_in(root);
}

template <typename cactus>
const cactus treap<cactus>::pre_in(const cactus v){
	int pos=root;
	cactus res=INF;
	while(pos){
		if(v>tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].right;
		}else{
			pos=tr[pos].left;
		}
	}
	return res;
}

template <typename cactus>
const cactus treap<cactus>::suc_in(const cactus v){
	int pos=root;
	cactus res=-INF;
	while(pos){
		if(v<tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].left;
		}else{
			pos=tr[pos].right;
		}
	}
	return res;
}

template <typename cactus>
void treap<cactus>::init(void){
	tr[0]=treap_node <cactus> (0,0,0,0,-1,0);
	n=0;
	root=0;
}

template <typename cactus>
void treap<cactus>::insert_in(cactus v){
	if(n==0){
		tr[1]=treap_node <cactus> (0,0,0,v,rand_c(),1);
		root=1;
		n=1;
		return;
	}
	int px=find_or_get_p(v);
	if(px<0){
		return;
	}
	n++;
	tr[n].p=px;
	if(tr[px].v>v){
		tr[px].left=n;
	}else{
		tr[px].right=n;
	}
	tr[n].left=0;
	tr[n].right=0;
	tr[n].v=v;
	tr[n].priority=rand_c();
	while(tr[n].p&&tr[n].priority<tr[tr[n].p].priority){
		if(lrson(n)){
			zag(n);
		}else{
			zig(n);
		}
	}
	px=tr[n].p;
	while(px){
		resize(px);
		px=tr[px].p;
	}
}

template <typename cactus>
void treap<cactus>::del_in(const cactus v){
	if(n==0||n==1){
		n=0;
		return;
	}
	int px=find_or_get_p(v);
	if(px>0){
		return;
	}
	px=-px;
	while(1){
		if(tr[px].left==0){
			if(tr[px].right==0){
				int pp=px;
				tr[pp].size=0;
				if(lrson(pp)){
					tr[tr[pp].p].right=0;
				}else{
					tr[tr[pp].p].left=0;
				}
				pp=tr[pp].p;
				while(pp){
					resize(pp);
					pp=tr[pp].p;
				}
				release_empty(px);
				return;
			}else{
				left_rotate(px);
			}
		}else{
			if(tr[px].right==0){
				right_rotate(px);
			}else{
				if(tr[tr[px].left].priority<tr[tr[px].right].priority){
					right_rotate(px);
				}else{
					left_rotate(px);
				}
			}
		}
	}
}

template <typename cactus>
const int treap<cactus>::rank_inline(const int p,const cactus v){
	if(tr[p].v>v){
		return rank_inline(tr[p].left,v);
	}else{
		if(tr[p].v<v){
			return rank_inline(tr[p].right,v)+1+tr[tr[p].left].size;
		}else{
			return 1+tr[tr[p].left].size;
		}
	}
}

template <typename cactus>
const cactus treap<cactus>::kth_in_root(const int rootx,const int kth){
	if(tr[rootx].size==1){
		return tr[rootx].v;
	}
	if(tr[rootx].left==0){
		if(kth==1){
			return tr[rootx].v;
		}
		return kth_in_root(tr[rootx].right,kth-1);
	}else{
		if(kth>tr[tr[rootx].left].size+1){
			return kth_in_root(tr[rootx].right,kth-tr[tr[rootx].left].size-1);
		}else{
			if(kth==tr[tr[rootx].left].size+1){
				return tr[rootx].v;
			}else{
				return kth_in_root(tr[rootx].left,kth);
			}
		}
	}
}

template <typename cactus>
const cactus treap<cactus>::kth_in(const int kth){
	return kth_in_root(root,kth);
}

