			px=tr[px].p;
		}
		return;
	}
	while(1){
		if(tr[px].left==0){
			if(tr[px].right==0){
				int pp=px;
				tr[pp].size=0;
				if(lrson(pp)){
					tr[tr[pp].p].right=0;
				}else{
					tr[tr[pp].p].left=0;
				}
				pp=tr[pp].p;
				while(pp){
					resize(pp);
					pp=tr[pp].p;
				}
				release_empty(px);
				return;
			}else{
				left_rotate(px);
			}
		}else{
			if(tr[px].right==0){
				right_rotate(px);
			}else{
				if(tr[tr[px].left].priority<tr[tr[px].right].priority){
					right_rotate(px);
				}else{
					left_rotate(px);
				}
			}
		}
	}
}

template <typename cactus>
const int multi_treap<cactus>::rank_inline(const int p,const cactus v){
	if(tr[p].v>v){
		return rank_inline(tr[p].left,v);
	}else{
		if(tr[p].v<v){
			return rank_inline(tr[p].right,v)+tr[p].cnt+tr[tr[p].left].size;
		}else{
			return 1+tr[tr[p].left].size;
		}
	}
}

template <typename cactus>
const cactus multi_treap<cactus>::kth_in_root(const int rootx,const int kth){
	if(tr[rootx].left==0){
		if(kth<=tr[rootx].cnt){
			return tr[rootx].v;
		}
		return kth_in_root(tr[rootx].right,kth-tr[rootx].cnt);
	}else{
		if(kth>tr[tr[rootx].left].size+tr[rootx].cnt){
			return kth_in_root(tr[rootx].right,kth-tr[tr[rootx].left].size-tr[rootx].cnt);
		}else{
			if(kth<=tr[tr[rootx].left].size){
				return kth_in_root(tr[rootx].left,kth);
			}else{
				return tr[rootx].v;
			}
		}
	}
}

template <typename cactus>
const int multi_treap<cactus>::kth_in(const int kth){
	return kth_in_root(root,kth);
}

