template <typename cactus>
class single_block{
	friend class block_list<cactus>;
	private:
		cactus c[15];
		int len;
		int pre;
		int nex;
		single_block(void);
		const single_block resize(const int p);
		void connect(const single_block bk);
};

template <typename cactus>
single_block<cactus>::single_block(void){
	len=0;
	pre=-1;
	nex=-1;
}

template <typename cactus>
const single_block<cactus> single_block<cactus>::resize(const int p){//the splitted block includes p
	single_block bk;
	for(int i=p;i<len;i++){
		bk.c[bk.len]=c[i];
		bk.len++;
	}
	len=p;
	return bk;
}

template <typename cactus>
void single_block<cactus>::connect(const single_block bk){
	for(int i=0;i<bk.len;i++,len++){
		c[len]=bk.c[i];
	}
}



template <typename cactus>
class block_list{//numbers start from 0
	public:
		cactus null_block;
	private:
		int m_sz;
		single_block<cactus> b[MAXNUM];
		int n;
		int n_sz;
		int root;
		void renew_m(void);
		void release_empty(const int pos);
		void split_in(const int pos,const int in_p);
		void merge_in(const int pos1,const int pos2);
		const cactus get_pos_in(const int bk_n,const int p);
		cactus& get_value_in(int pos_n);
		void maintain_n(void);
		void point_insert_in(int pos,const cactus v);
		void point_del_in(const int pos);
	public:
		block_list(void);
		cactus& operator[](const cactus pos);
		void insert(const int pos,const cactus v);
		void del(const int pos);
		void insert(const cactus v);
		void del(void);
};

template <typename cactus>
void block_list<cactus>::renew_m(void){
	m_sz=sqrt_c(n_sz);
}

template <typename cactus>
void block_list<cactus>::release_empty(const int pos){
	if(pos==n-1){
		n--;
		return;
	}
	if(n-1==root){
		root=pos;
	}
	b[pos]=b[n-1];
	if(b[pos].nex!=-1){
		b[b[pos].nex].pre=pos;
	}
	if(b[pos].pre!=-1){
		b[b[pos].pre].nex=pos;
	}
	n--;
	return;
}

template <typename cactus>
void block_list<cactus>::split_in(const int pos,const int in_p){
	b[n]=b[pos].resize(in_p);
	b[n].nex=b[pos].nex;
	b[n].pre=pos;
	b[pos].nex=n;
	n++;
}

template <typename cactus>
void block_list<cactus>::merge_in(const int pos1,const int pos2){//pos1<pos2
	b[pos1].connect(b[pos2]);
	b[pos1].nex=b[pos2].nex;
	if(b[pos2].nex!=-1){
		b[b[pos2].nex].pre=pos1;
	}
	release_empty(pos2);
}

template <typename cactus>
const cactus block_list<cactus>::get_pos_in(const int bk_n,const int p){
	return b[bk_n].c[p];
}

template <typename cactus>
cactus& block_list<cactus>::get_value_in(int pos_n){
	if(pos_n>=n_sz||pos_n<0){
		return null_block;
	}
	int cur=root;
	while(pos_n>=b[cur].len){
		pos_n-=b[cur].len;
		cur=b[cur].nex;
	}
	return b[cur].c[pos_n];
}

template <typename cactus>
void block_list<cactus>::maintain_n(void){
	renew_m();
	for(int i=root;i!=-1;i=b[i].nex){
		if(b[i].len>m_sz){
			split_in(i,b[i].len/2);
		}else{
			if(b[i].pre==-1){
				if(b[i].nex==-1){
					return;
				}else{
					if(b[i].len+b[b[i].nex].len<=m_sz){
						merge_in(i,b[i].nex);
					}
				}
			}else{
				if(b[i].nex==-1){
					if(b[b[i].pre].len+b[i].len<=m_sz){
						merge_in(b[i].pre,i);
					}
				}else{
					if(b[i].len+b[b[i].nex].len<=m_sz){
						merge_in(i,b[i].nex);
						continue;
					}
					if(b[b[i].pre].len+b[i].len<=m_sz){
						merge_in(b[i].pre,i);
						continue;
					}
				}
			}
		}
	}
}

template <typename cactus>
void block_list<cactus>::point_insert_in(int pos,const cactus v){
	if(pos>n_sz||pos<0){
		return;
	}
	if(n_sz==0){
		root=0;
		b[0]=single_block<cactus>();
		n=1;
		n_sz=1;
		b[0].len=1;
		b[0].c[0]=v;
		return;
	}
	int bk_p=root;
	while(pos>=b[bk_p].len+1){
		pos-=b[bk_p].len;
		bk_p=b[bk_p].nex;
	}
	for(int i=b[bk_p].len;i>pos;i--){
		b[bk_p].c[i]=b[bk_p].c[i-1];
	}
	b[bk_p].c[pos]=v;
	b[bk_p].len++;
	n_sz++;
	maintain_n();
}

template <typename cactus>
void block_list<cactus>::point_del_in(const int pos){
	if(pos>=n_sz||pos<0){
		return;
	}
	int bk_p=root;
	while(pos>=b[bk_p].len+1){
		pos-=b[bk_p].len;
		bk_p=b[bk_p].nex;
	}
	if(b[bk_p].len==1){
		release_empty(bk_p);
		return;
	}
	for(int i=pos;i<b[bk_p].len;i++){
		b[bk_p].c[i]=b[bk_p].c[i+1];
	}
	b[bk_p].len--;
	maintain_n();
}

template <typename cactus>
block_list<cactus>::block_list(void){
	n=0;
	root=0;
	n_sz=0;
	m_sz=0;
}

template <typename cactus>
cactus& block_list<cactus>::operator[](const cactus pos){
	return get_value_in(pos);
}

template <typename cactus>
void block_list<cactus>::insert(const int pos,const cactus v){
	point_insert_in(pos,v);
}

template <typename cactus>
void block_list<cactus>::del(const int pos){
	point_del_in(pos);
}

template <typename cactus>
void block_list<cactus>::insert(const cactus v){
	point_insert_in(n_sz,v);
}

template <typename cactus>
void block_list<cactus>::del(void){
	point_del_in(n_sz-1);
}

