template <typename cactus>
class fhq_treap{
	private:
		fhq_node <cactus> tr[MAXN];
		int n;
		int root;
		int em[MAXN],emp;
		void init(void);
		int seed=207803;
		inline const int rand_c(void);
		void resize(const int p);
		void release_empty(const int p);
		void split_by_value(const int pos,const cactus val,int &root1,int &root2);
		void split_by_size(const int pos,const int sz,int &root1,int &root2);
		void merge_in(int &rootx,const int pos1,const int pos2);
		const bool find_p(const cactus v);
		const cactus get_max_in(const int p);
		const cactus get_min_in(const int p);
		const cactus max_in(void);
		const cactus min_in(void);
		const cactus pre_in(const cactus v);
		const cactus suc_in(const cactus v);
		const int rank_inline(const int p,const cactus v);
		const cactus kth_in_root(const int rootx,const int kth);
		const cactus kth_in(const int kth);
		const int rank_in(const cactus v);
		void printxroot(int p);
		void insert_in(const cactus v);
		void del_in(const cactus v);
	public:
		fhq_treap(void);
		const SIZE_C size(void);
		void insert(const cactus v);
		void del(const cactus v);
		const cactus max(void);
		const cactus min(void);
		const bool find(const cactus v);
		const cactus pre(const cactus v);
		const cactus suc(const cactus v);
		const int rank(const cactus v);
		const cactus kth(const int k);
};

template <typename cactus>
void fhq_treap<cactus>::init(void){
	n=0;
	root=0;
	emp=0;
}

template <typename cactus>
inline const int fhq_treap<cactus>::rand_c(void){
    return seed=(int)((seed*4827153LL+114514)%2147483647);
}

template <typename cactus>
void fhq_treap<cactus>::resize(const int p){
	tr[0].size=0;
	tr[p].size=tr[tr[p].left].size+tr[tr[p].right].size+1;
}

template <typename cactus>
void fhq_treap<cactus>::release_empty(const int p){
	em[emp]=p;
	emp++;
}

template <typename cactus>
void fhq_treap<cactus>::split_by_value(const int pos,const cactus val,int &root1,int &root2){
	if(pos==0){
		root1=0;
		root2=0;
		return;
	}
	if(tr[pos].v>val){
		root2=pos;
		split_by_value(tr[pos].left,val,root1,tr[root2].left);
	}else{
		root1=pos;
		split_by_value(tr[pos].right,val,tr[root1].right,root2);
	}
	resize(pos);
}

template <typename cactus>
void fhq_treap<cactus>::split_by_size(const int pos,const int sz,int &root1,int &root2){
	if(pos==0){
		root1=0;
		root2=0;
		return;
	}
	if(tr[pos].v>sz){
		root2=pos;
		split_by_size(pos,sz,root1,tr[root2].left);
	}else{
		root1=pos;
		split_by_size(pos,sz-tr[tr[pos].left].size-1,tr[root1].left,root2);
	}
	resize(pos);
}

template <typename cactus>
void fhq_treap<cactus>::merge_in(int &rootx,const int pos1,const int pos2){//pos1<pos2
	if(pos1==0||pos2==0){
		rootx=pos1+pos2;
		return;
	}
	if(tr[pos1].priority<tr[pos2].priority){
		rootx=pos1;
		merge_in(tr[rootx].right,tr[pos1].right,pos2);
		resize(rootx);
	}else{
		rootx=pos2;
		merge_in(tr[rootx].left,pos1,tr[pos2].left);
		resize(rootx);
	}
}

template <typename cactus>
const bool fhq_treap<cactus>::find_p(const cactus v){//returns 0-pos if found and parent if not
	int pos=root;
	while(1){
		if(tr[pos].v>v){
			if(tr[pos].left==0){
				return 0;
			}else{
				pos=tr[pos].left;
				continue;
			}
		}else{
			if(tr[pos].v<v){
				if(tr[pos].right==0){
					return 0;
				}else{
					pos=tr[pos].right;
					continue;
				}
			}else{
				return 1;
			}
		}
	}
}

template <typename cactus>
const cactus fhq_treap<cactus>::get_max_in(const int p){
	if(tr[p].right==0){
		return tr[p].v;
	}
	return get_max_in(tr[p].right);
}

template <typename cactus>
const cactus fhq_treap<cactus>::get_min_in(const int p){
	if(tr[p].left==0){
		return tr[p].v;
	}
	return get_min_in(tr[p].left);
}

template <typename cactus>
const cactus fhq_treap<cactus>::max_in(void){
	return get_max_in(root);
}

template <typename cactus>
const cactus fhq_treap<cactus>::min_in(void){
	return get_min_in(root);
}

template <typename cactus>
const cactus fhq_treap<cactus>::pre_in(const cactus v){
	int pos=root;
	cactus res=INF;
	while(pos){
		if(v>tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].right;
		}else{
			pos=tr[pos].left;
		}
	}
	return res;
}

template <typename cactus>
const cactus fhq_treap<cactus>::suc_in(const cactus v){
	int pos=root;
	cactus res=-INF;
	while(pos){
		if(v<tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].left;
		}else{
			pos=tr[pos].right;
		}
	}
	return res;
}

template <typename cactus>
const int fhq_treap<cactus>::rank_inline(const int p,const cactus v){
	if(tr[p].v>v){
		return rank_inline(tr[p].left,v);
	}else{
		if(tr[p].v<v){
			return rank_inline(tr[p].right,v)+1+tr[tr[p].left].size;
		}else{
			return 1+tr[tr[p].left].size;
		}
	}
}

template <typename cactus>
const cactus fhq_treap<cactus>::kth_in_root(const int rootx,const int kth){
	if(tr[rootx].size==1){
		return tr[rootx].v;
	}
	if(tr[rootx].left==0){
		if(kth==1){
			return tr[rootx].v;
		}
		return kth_in_root(tr[rootx].right,kth-1);
	}else{
		if(kth>tr[tr[rootx].left].size+1){
			return kth_in_root(tr[rootx].right,kth-tr[tr[rootx].left].size-1);
		}else{
			if(kth==tr[tr[rootx].left].size+1){
				return tr[rootx].v;
			}else{
				return kth_in_root(tr[rootx].left,kth);
			}
		}
	}
}

template <typename cactus>
const cactus fhq_treap<cactus>::kth_in(const int kth){
	return kth_in_root(root,kth);
}

template <typename cactus>
const int fhq_treap<cactus>::rank_in(const cactus v){
	return rank_inline(root,v);
}

template <typename cactus>
void fhq_treap<cactus>::printxroot(int p){
	if(p==0){
		return;
	}
	printxroot(tr[p].left);
	cactusout<<tr[p].v<<space;
	printxroot(tr[p].right);
}

template <typename cactus>
void fhq_treap<cactus>::insert_in(const cactus v){
	int r1,r2;
	if(find_p(v)){
		return;
	}
	split_by_value(root,v,r1,r2);
	if(emp){
		emp--;
		tr[em[emp]]=fhq_node <cactus> (v,0,0,1,rand_c());
		int x;
		merge_in(x,r1,em[emp]);
		merge_in(root,x,r2);
	}else{
		n++;
		tr[n]=fhq_node <cactus> (v,0,0,1,rand_c());
		int x;
		merge_in(x,r1,n);
		merge_in(root,x,r2);	
	}
}

template <typename cactus>
void fhq_treap<cactus>::del_in(const cactus v){
	if(find_p(v)){
		int r1,rv,r2;
		split_by_value(root,v-1,r1,rv);
		split_by_value(rv,v,rv,r2);
		release_empty(rv);
		merge_in(root,r1,r2);
	}else{
		return;
	}
}

