template <typename cactus>
void multi_fhq_treap<cactus>::init(void){
	n=0;
	root=0;
	emp=0;
}

template <typename cactus>
inline const int multi_fhq_treap<cactus>::rand_c(void){
    return seed=(int)((seed*4827153LL+114514)%2147483647);
}

template <typename cactus>
void multi_fhq_treap<cactus>::resize(const int p){
	tr[0].size=0;
	tr[p].size=tr[tr[p].left].size+tr[tr[p].right].size+tr[p].cnt;
}

template <typename cactus>
void multi_fhq_treap<cactus>::release_empty(const int p){
	em[emp]=p;
	emp++;
}

template <typename cactus>
void multi_fhq_treap<cactus>::split_by_value(const int pos,const cactus val,int &root1,int &root2){
	if(pos==0){
		root1=0;
		root2=0;
		return;
	}
	if(tr[pos].v>val){
		root2=pos;
		split_by_value(tr[pos].left,val,root1,tr[root2].left);
	}else{
		root1=pos;
		split_by_value(tr[pos].right,val,tr[root1].right,root2);
	}
	resize(pos);
}

template <typename cactus>
void multi_fhq_treap<cactus>::split_by_size(const int pos,const int sz,int &root1,int &root2){
	if(pos==0){
		root1=0;
		root2=0;
		return;
	}
	if(tr[pos].size>sz){
		root2=pos;
		split_by_size(pos,sz,root1,tr[root2].left);
	}else{
		root1=pos;
		split_by_size(pos,sz-tr[tr[pos].left].size-1,tr[root1].left,root2);
	}
	resize(pos);
}

template <typename cactus>
void multi_fhq_treap<cactus>::merge_in(int &rootx,const int pos1,const int pos2){//pos1<pos2
	if(pos1==0||pos2==0){
		rootx=pos1+pos2;
		return;
	}
	if(tr[pos1].priority<tr[pos2].priority){
		rootx=pos1;
		merge_in(tr[rootx].right,tr[pos1].right,pos2);
		resize(rootx);
	}else{
		rootx=pos2;
		merge_in(tr[rootx].left,pos1,tr[pos2].left);
		resize(rootx);
	}
}

template <typename cactus>
const int multi_fhq_treap<cactus>::find_p(const cactus v){
	int pos=root;
	while(1){
		if(tr[pos].v>v){
			if(tr[pos].left==0){
				return 0;
			}else{
				pos=tr[pos].left;
				continue;
			}
		}else{
			if(tr[pos].v<v){
				if(tr[pos].right==0){
					return 0;
				}else{
					pos=tr[pos].right;
					continue;
				}
			}else{
				return pos;
			}
		}
	}
}

template <typename cactus>
void multi_fhq_treap<cactus>::find_and_add(const cactus v){
	int pos=root;
	while(1){
		tr[pos].size++;
		if(tr[pos].v>v){
			if(tr[pos].left==0){
				return;
			}else{
				pos=tr[pos].left;
				continue;
			}
		}else{
			if(tr[pos].v<v){
				if(tr[pos].right==0){
					return;
				}else{
					pos=tr[pos].right;
					continue;
				}
			}else{
				return;
			}
		}
	}
}

template <typename cactus>
void multi_fhq_treap<cactus>::find_and_minus(const cactus v){
	int pos=root;
	while(1){
		tr[pos].size--;
		if(tr[pos].v>v){
			if(tr[pos].left==0){
				return;
			}else{
				pos=tr[pos].left;
				continue;
			}
		}else{
			if(tr[pos].v<v){
				if(tr[pos].right==0){
					return;
				}else{
					pos=tr[pos].right;
					continue;
				}
			}else{
				return;
			}
		}
	}
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::get_max_in(const int p){
	if(tr[p].right==0){
		return tr[p].v;
	}
	return get_max_in(tr[p].right);
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::get_min_in(const int p){
	if(tr[p].left==0){
		return tr[p].v;
	}
	return get_min_in(tr[p].left);
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::max_in(void){
	return get_max_in(root);
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::min_in(void){
	return get_min_in(root);
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::pre_in(const cactus v){
	int pos=root;
	cactus res=INF;
	while(pos){
		if(v>tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].right;
		}else{
			pos=tr[pos].left;
		}
	}
	return res;
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::suc_in(const cactus v){
	int pos=root;
	cactus res=-INF;
	while(pos){
		if(v<tr[pos].v){
			res=tr[pos].v;
			pos=tr[pos].left;
		}else{
			pos=tr[pos].right;
		}
	}
	return res;
}

template <typename cactus>
const int multi_fhq_treap<cactus>::rank_inline(const int p,const cactus v){
	tr[0].size=0;
	if(tr[p].v>v){
		return rank_inline(tr[p].left,v);
	}else{
		if(tr[p].v<v){
			return rank_inline(tr[p].right,v)+tr[p].cnt+tr[tr[p].left].size;
		}else{
			return 1+tr[tr[p].left].size;
		}
	}
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::kth_in_root(const int rootx,const int kth){
	if(tr[rootx].left==0){
		if(kth<=tr[rootx].cnt){
			return tr[rootx].v;
		}
		return kth_in_root(tr[rootx].right,kth-tr[rootx].cnt);
	}else{
		if(kth>tr[tr[rootx].left].size+tr[rootx].cnt){
			return kth_in_root(tr[rootx].right,kth-tr[tr[rootx].left].size-tr[rootx].cnt);
		}else{
			if(kth<=tr[tr[rootx].left].size){
				return kth_in_root(tr[rootx].left,kth);
			}else{
				return tr[rootx].v;
			}
		}
	}
}

template <typename cactus>
const cactus multi_fhq_treap<cactus>::kth_in(const int kth){
	return kth_in_root(root,kth);
}

template <typename cactus>
const int multi_fhq_treap<cactus>::rank_in(const cactus v){
	return rank_inline(root,v);
}

template <typename cactus>
void multi_fhq_treap<cactus>::printxroot(int p){
	if(p==0){
		return;
	}
	printxroot(tr[p].left);
	cactusout<<tr[p].v<<space;
	printxroot(tr[p].right);
}

template <typename cactus>
void multi_fhq_treap<cactus>::insert_in(const cactus v){
	if(n==0){
		tr[0]=multi_fhq_node <cactus> (0,0,0,0,-1,0);
		tr[1]=multi_fhq_node <cactus> (v,0,0,1,rand_c(),1);
		n=1;
		root=1;
		return;
	}
	int r1,r2;
	int k;
	if(k=find_p(v)){
		tr[k].cnt++;
		find_and_add(v);
		return;
	}
	split_by_value(root,v,r1,r2);
	if(emp){
		emp--;
		tr[em[emp]]=multi_fhq_node <cactus> (v,0,0,1,rand_c(),1);
		int x;
		merge_in(x,r1,em[emp]);
		merge_in(root,x,r2);
	}else{
		n++;
		tr[n]=multi_fhq_node <cactus> (v,0,0,1,rand_c(),1);
		int x;
		merge_in(x,r1,n);
		merge_in(root,x,r2);	
	}
}

template <typename cactus>
void multi_fhq_treap<cactus>::del_in(const cactus v){
	if(n==0||n==1){
		n=0;
		return;
	}
	int k;
	if(k=find_p(v)){
		if(tr[k].cnt>1){
			tr[k].cnt--;
			find_and_minus(v);
			return;
		}
		int r1,rv,r2;
		split_by_value(root,v-1,r1,rv);
		split_by_value(rv,v,rv,r2);
		release_empty(rv);
		merge_in(root,r1,r2);
	}else{
		return;
	}
}

