		void init(cactus *p1,cactus *p2);
		void add_linear_in(const int pre,const int k,const int l,const int r,const int p,const cactus val);
		void add_linear(const int pre_root,const int p,const cactus val);
		const cactus point_query_in(const int rootx,const int l,const int r,const int p);
		const cactus range_query_in(const int rootx,const int l,const int r,const int pl,const int pr);
		void add_in(const int p,const cactus val,const int version);
		void simple_add_in(const int p,const cactus val);
		const cactus find_in(const int p,const int version);
		const cactus simple_find_in(const int p);
		const cactus max_in(const int pl,const int pr,const int version);
		const cactus simple_max_in(const int pl,const int pr);
	public:
		max_persistent_segment_tree(void);
		max_persistent_segment_tree(const int size);
		max_persistent_segment_tree(cactus *p1,cactus *p2);
