template <typename cactus>
const int max_persistent_segment_tree<cactus>::new_node(void){
	n++;
	return n-1;
}

template <typename cactus>
const int max_persistent_segment_tree<cactus>::new_node(const cactus val){
	tr[n]=persistent_node <cactus> (-1,-1,val);
	n++;
	return n-1;
}

template <typename cactus>
const int max_persistent_segment_tree<cactus>::new_node(const int l,const int r,const int val){
	tr[n]=persistent_node <cactus> (l,r,val);
	n++;
	return n-1;
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::build_in_a(const int l,const int r,const int p){
	if(l==r){
		tr[p].v=a[l];
		return;
	}
	tr[p].left=new_node();
	tr[p].right=new_node();
	int mid=(l+r)>>1;
	build_in_a(l,mid,tr[p].left);
	build_in_a(mid+1,r,tr[p].right);
	tr[p].v=tr[tr[p].left].v>tr[tr[p].right].v?tr[tr[p].left].v:tr[tr[p].right].v;
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::build_by_a(void){
	n=1;
	len=1;
	root[0]=0;
	build_in_a(1,num,0);
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::build_in_empty(const int l,const int r,const int p){
	if(l==r){
		return;
	}
	tr[p].left=new_node();
	tr[p].right=new_node();
	int mid=(l+r)>>1;
	build_in_empty(l,mid,tr[p].left);
	build_in_empty(mid+1,r,tr[p].right);
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::build_empty(void){
	n=1;
	len=1;
	root[0]=0;
	build_in_empty(1,num,0);
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::init_empty(const int sz){
	num=sz;
	build_empty();
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::init(cactus *p1,cactus *p2){
	num=p2-p1;
	for(int i=1;i<=num;i++){
		a[i]=*p1;
		p1++;
	}
	build_by_a();
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::add_linear_in(const int pre,const int k,const int l,const int r,const int p,const cactus val){
	if(l==r){
		return;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		tr[k].left=tr[pre].left;
		tr[k].right=new_node(tr[tr[pre].right].v>val?tr[tr[pre].right].v:val);
		add_linear_in(tr[pre].right,tr[k].right,mid+1,r,p,val);
	}else{
		tr[k].right=tr[pre].right;
		tr[k].left=new_node(tr[tr[pre].left].v>val?tr[tr[pre].left].v:val);
		add_linear_in(tr[pre].left,tr[k].left,l,mid,p,val);
	}
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::add_linear(const int pre_root,const int p,const cactus val){
	root[len]=new_node(tr[pre_root].v>val?tr[pre_root].v:val);
	add_linear_in(pre_root,root[len],1,num,p,val);
	len++;
}

template <typename cactus>
const cactus max_persistent_segment_tree<cactus>::point_query_in(const int rootx,const int l,const int r,const int p){
	if(l==r){
		return tr[rootx].v;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		return point_query_in(tr[rootx].right,mid+1,r,p);
	}else{
		return point_query_in(tr[rootx].left,l,mid,p);
	}
}

template <typename cactus>
const cactus max_persistent_segment_tree<cactus>::range_query_in(const int rootx,const int l,const int r,const int pl,const int pr){
	if(inrange(pl,pr,l,r)){
		return tr[rootx].v;
	}
	if(outofrange(pl,pr,l,r)){
		return 0;
	}
	int mid=(l+r)>>1;
	int ml=range_query_in(tr[rootx].left,l,mid,pl,pr);
	int mr=range_query_in(tr[rootx].right,mid+1,r,pl,pr);
	return ml>mr?ml:mr;
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::add_in(const int p,const cactus val,const int version){
	add_linear(root[version],p,val);
}

template <typename cactus>
void max_persistent_segment_tree<cactus>::simple_add_in(const int p,const cactus val){
	add_linear(root[len-1],p,val);
}

template <typename cactus>
const cactus max_persistent_segment_tree<cactus>::find_in(const int p,const int version){
	return point_query_in(root[version],1,num,p);
}

template <typename cactus>
const cactus max_persistent_segment_tree<cactus>::simple_find_in(const int p){
	return point_query_in(root[len-1],1,num,p);
}

template <typename cactus>
const cactus max_persistent_segment_tree<cactus>::max_in(const int pl,const int pr,const int version){
	return range_query_in(root[version],1,num,pl,pr);
}

template <typename cactus>
const cactus max_persistent_segment_tree<cactus>::simple_max_in(const int pl,const int pr){
	return range_query_in(root[len-1],1,num,pl,pr);
}

