	n++;
	return n-1;
}

template <typename cactus>
void min_persistent_segment_tree<cactus>::build_in_a(const int l,const int r,const int p){
	if(l==r){
		tr[p].v=a[l];
		return;
	}
	tr[p].left=new_node();
	tr[p].right=new_node();
	int mid=(l+r)>>1;
	build_in_a(l,mid,tr[p].left);
	build_in_a(mid+1,r,tr[p].right);
	tr[p].v=tr[tr[p].left].v<tr[tr[p].right].v?tr[tr[p].left].v:tr[tr[p].right].v;
}

template <typename cactus>
void min_persistent_segment_tree<cactus>::build_by_a(void){
	n=1;
	len=1;
	root[0]=0;
