template <typename cactus>
void min_persistent_segment_tree<cactus>::init(cactus *p1,cactus *p2){
	num=p2-p1;
	for(int i=1;i<=num;i++){
		a[i]=*p1;
		p1++;
	}
	build_by_a();
}

template <typename cactus>
void min_persistent_segment_tree<cactus>::add_linear_in(const int pre,const int k,const int l,const int r,const int p,const cactus val){
	if(l==r){
		return;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		tr[k].left=tr[pre].left;
		tr[k].right=new_node(tr[tr[pre].right].v<val?tr[tr[pre].right].v:val);
		add_linear_in(tr[pre].right,tr[k].right,mid+1,r,p,val);
	}else{
		tr[k].right=tr[pre].right;
		tr[k].left=new_node(tr[tr[pre].left].v<val?tr[tr[pre].left].v:val);
		add_linear_in(tr[pre].left,tr[k].left,l,mid,p,val);
	}
}

template <typename cactus>
void min_persistent_segment_tree<cactus>::add_linear(const int pre_root,const int p,const cactus val){
	root[len]=new_node(tr[pre_root].v>val?tr[pre_root].v:val);
	add_linear_in(pre_root,root[len],1,num,p,val);
	len++;
}

template <typename cactus>
const cactus min_persistent_segment_tree<cactus>::point_query_in(const int rootx,const int l,const int r,const int p){
	if(l==r){
		return tr[rootx].v;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		return point_query_in(tr[rootx].right,mid+1,r,p);
	}else{
		return point_query_in(tr[rootx].left,l,mid,p);
	}
}

template <typename cactus>
const cactus min_persistent_segment_tree<cactus>::range_query_in(const int rootx,const int l,const int r,const int pl,const int pr){
	if(inrange(pl,pr,l,r)){
		return tr[rootx].v;
	}
	if(outofrange(pl,pr,l,r)){
		return 0;
	}
	int mid=(l+r)>>1;
	int ml=range_query_in(tr[rootx].left,l,mid,pl,pr);
	int mr=range_query_in(tr[rootx].right,mid+1,r,pl,pr);
	return ml<mr?ml:mr;
}

