class union_node{
	private:
		int left,right;
		int f,h;
		union_node(void);
		union_node(int l,int r,int fa,int ht);
		friend class persistent_union_set;
};

union_node::union_node(void){
	h=1;
}

union_node::union_node(int l,int r,int fa,int ht){
	left=l;
	right=r;
	f=fa;
	h=ht;
}



class persistent_union_set{
	private:
		union_node u[MAXN];
		int n;
		int root[MAXNUM*2];
		int r;
		int num;
		int new_node(void);
		int new_node(int l,int r,int fa,int ht);
		int find_r(int k,int a);
		void build_in(int k,int l,int r);
		void new_line(int pre,int k,int l,int r,int p,int fa,int d_ht);
		int build_new(int p_root,int p,int fa,int d_ht);
		int get_pos(int k,int l,int r,int p);;
	public:	
		explicit persistent_union_set(const int range);
		void merge(const int version,int a,int b);
		void simple_merge(const int a,const int b);
		const bool relate(const int version,int a,int b);
		const bool simple_relate(const int a,const int b);
		void copy(const int version);
		void simple_copy(void);
};

int persistent_union_set::new_node(void){
	n++;
	return n-1;
}

int persistent_union_set::new_node(int l,int r,int fa,int ht){
	u[n]=union_node(l,r,fa,ht);
	n++;
	return n-1;
}

void persistent_union_set::build_in(int k,int l,int r){
	if(l==r){
		u[k].f=l;
		return;
	}
	u[k].left=new_node();
	u[k].right=new_node();
	int mid=(l+r)>>1;
	build_in(u[k].left,l,mid);
	build_in(u[k].right,mid+1,r);
}

void persistent_union_set::new_line(int pre,int k,int l,int r,int p,int fa,int d_ht){
	if(l==r){
		u[k]=u[pre];
		u[k].f=fa;
		u[k].h+=d_ht;
		return;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		u[k]=u[pre];
		u[k].right=new_node();
		new_line(u[pre].right,u[k].right,mid+1,r,p,fa,d_ht);
	}else{
		u[k]=u[pre];
		u[k].left=new_node();
		new_line(u[pre].left,u[k].left,l,mid,p,fa,d_ht);
	}
}

int persistent_union_set::build_new(int p_root,int p,int fa,int d_ht){
	int ret=new_node();
	new_line(p_root,ret,1,num,p,fa,d_ht);
	return ret;
}

int persistent_union_set::get_pos(int k,int l,int r,int p){
	if(l==r){
		return k;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		return get_pos(u[k].right,mid+1,r,p);
	}else{
		return get_pos(u[k].left,l,mid,p);
	}
}

int persistent_union_set::find_r(int k,int a){
	int b=get_pos(k,1,num,a);
	if(u[b].f==a){
		return a;
	}
	return find_r(k,u[b].f);
}

persistent_union_set::persistent_union_set(const int range){
	num=range;
	n=1;
	build_in(0,1,num);
	root[0]=0;
	r=1;
}

void persistent_union_set::merge(const int version,int a,int b){
	a=find_r(root[version],a);
	b=find_r(root[version],b);
	int pa=get_pos(root[version],1,num,a);
	int pb=get_pos(root[version],1,num,b);
	if(pa==pb){
		root[r]=root[version];
		r++;
		return;
	}
	if(u[pa].h>u[pb].h){
		root[r]=build_new(root[version],b,a,0);
		r++;
	}else{
		if(u[pa].h==u[pb].h){
			root[r]=build_new(build_new(root[version],b,a,0),a,a,1);
			r++;
		}else{
			root[r]=build_new(root[version],a,b,0);
			r++;
		}
	}
}

void persistent_union_set::simple_merge(const int a,const int b){
	merge(r-1,a,b);
}

const bool persistent_union_set::relate(const int version,int a,int b){
	a=find_r(root[version],a);
	b=find_r(root[version],b);
	return a==b;
}

const bool persistent_union_set::simple_relate(const int a,const int b){
	return relate(r-1,a,b);
}

void persistent_union_set::copy(const int version){
	root[r]=root[version];
	r++;
}

void persistent_union_set::simple_copy(void){
	copy(r-1);
}

