template <typename cactus>
void reverse_splay<cactus>::resize(int p){
	tr[p].size=1;
	if(tr[p].left!=-1){
		tr[p].size+=tr[tr[p].left].size;
	}
	if(tr[p].right!=-1){
		tr[p].size+=tr[tr[p].right].size;
	}
}

template <typename cactus>
bool reverse_splay<cactus>::lrson(int p){
	return p==tr[tr[p].p].right;
}

template <typename cactus>
int reverse_splay<cactus>::new_node(int l,int r,int pa,int val,bool tags){
	tr[n]=reverse_splay_node<cactus>(l,r,pa,val,tags);
	n++;
	return n-1;
}

template <typename cactus>
int reverse_splay<cactus>::new_node(void){
	n++;
	return n-1;
}

template <typename cactus>
void reverse_splay<cactus>::built_in(int p,int l,int r){
	if(l==r){
		tr[p].v=l;
		return;
	}
	int mid=(l+r)>>1;
	tr[p].v=mid;
	if(l<mid){
		tr[p].left=new_node(-1,-1,p,0,0);
		built_in(tr[p].left,l,mid-1);
	}
	if(r>mid){
		tr[p].right=new_node(-1,-1,p,0,0);
		built_in(tr[p].right,mid+1,r);
	}
	resize(p);
}


template <typename cactus>
void reverse_splay<cactus>::build_a(void){
	n=1;
	root=0;
	built_in(0,0,num+1);
}

template <typename cactus>
void reverse_splay<cactus>::init(cactus *p1,cactus *p2){
	num=p2-p1;
	for(int i=1;i<=num;i++){
		a[i]=*p1;
		p1++;
	}
	build_a();
}

template <typename cactus>
void reverse_splay<cactus>::left_rotate(int p){
	int pa=tr[p].p;
	int rght=tr[p].right;
	int rl=tr[rght].left;

	if(p==root){
		root=rght;
		tr[rght].p=-1;
	}else{
		if(lrson(p)){
			tr[pa].right=rght;
			tr[rght].p=pa;
		}else{
			tr[pa].left=rght;
			tr[rght].p=pa;
		}
	}

	tr[p].right=rl;
	tr[rl].p=p;

	tr[rght].left=p;
	tr[p].p=rght;

	resize(p);
	resize(rght);
}

template <typename cactus>
void reverse_splay<cactus>::right_rotate(int p){
	int pa=tr[p].p;
	int lft=tr[p].left;
	int lr=tr[lft].right;

	if(p==root){
		tr[lft].p=-1;
		root=lft;
	}else{
		if(lrson(p)){
			tr[pa].right=lft;
			tr[lft].p=pa;
		}else{
			tr[pa].left=lft;
			tr[lft].p=pa;
		}
	}

	tr[p].left=lr;
	tr[lr].p=p;

	tr[lft].right=p;
	tr[p].p=lft;

	resize(p);
	resize(lft);
}

template <typename cactus>
void reverse_splay<cactus>::rotate_to(int p,int dtn){
	while(tr[p].p!=dtn){
		pushdown(tr[p].p);
		pushdown(p);
		if(lrson(p)){
			left_rotate(tr[p].p);
		}else{
			right_rotate(tr[p].p);
		}
	}
}

template <typename cactus>
void reverse_splay<cactus>::get_node(int p,int v,int dtn){
	v++;
	while(1){
		pushdown(p);
		if(tr[p].left==-1){
			if(v==1){
				break;
			}else{
				v--;
				p=tr[p].right;
			}
		}else{
			if(v==tr[tr[p].left].size+1){
				break;
			}else{
				if(v<=tr[tr[p].left].size){
					p=tr[p].left;
				}else{
					v-=(tr[tr[p].left].size+1);
					p=tr[p].right;
				}
			}
		}
	}
	rotate_to(p,dtn);
}

template <typename cactus>
void reverse_splay<cactus>::make_tag(int p){
	if(p==-1){
		return;
	}
	tr[p].tag^=1;
}

template <typename cactus>
void reverse_splay<cactus>::pushdown(int p){
	if(tr[p].tag){
		swap_c(tr[p].left,tr[p].right);
		tr[p].tag=0;
		make_tag(tr[p].left);
		make_tag(tr[p].right);
	}
}

template <typename cactus>
void reverse_splay<cactus>::reverse_in(int pl,int pr){
	get_node(root,pl-1,-1);
	get_node(root,pr+1,root);
	make_tag(tr[tr[root].right].left);
}

template <typename cactus>
void reverse_splay<cactus>::print_x_root(int rx){
	if(rx==-1){
		return;
	}
	pushdown(rx);
	print_x_root(tr[rx].left);
	if(tr[rx].v>0&&tr[rx].v<=num){
		cactusout<<a[tr[rx].v]<<space;
	}
	print_x_root(tr[rx].right);
}

template <typename cactus>
void reverse_splay<cactus>::renew_x_root(int rx){
	if(rx==-1){
		return;
	}
	pushdown(rx);
	renew_x_root(tr[rx].left);
	if(tr[rx].v>0&&tr[rx].v<=num){
		r[pt]=a[tr[rx].v];
	}
	pt++;
	renew_x_root(tr[rx].right);
}

template <typename cactus>
reverse_splay<cactus>::reverse_splay(cactus *p1,cactus *p2){
	init(p1,p2);
}

template <typename cactus>
const SIZE_C reverse_splay<cactus>::size(void){
	return num;
}

template <typename cactus>
void reverse_splay<cactus>::reverse(const int pl,const int pr){
	reverse_in(pl,pr);
}

template <typename cactus>
void reverse_splay<cactus>::print(void){
	print_x_root(root);
}

template <typename cactus>
const cactus* reverse_splay<cactus>::get(void){
	pt=1;
	renew_x_root(root);
	return r+1;
}

