template <typename cactus>
class reverse_fhq_treap{
	private:
		reverse_fhq_node<cactus> tr[MAXNUM];
		int n;
		int root;
		cactus a[MAXNUM];
		cactus r[MAXNUM];
		int num;
		int pt;
		int sk[MAXNUM];
		int skn;
		void resize(int p);
