template <typename cactus>
const SIZE_C reverse_fhq_treap<cactus>::size(void){
	return num;
}

template <typename cactus>
void reverse_fhq_treap<cactus>::resize(int p){
	tr[0].size=0;
	tr[p].size=1+tr[tr[p].left].size+tr[tr[p].right].size;
}

template <typename cactus>
int reverse_fhq_treap<cactus>::new_node(void){
	n++;
	return n;
}

template <typename cactus>
int reverse_fhq_treap<cactus>::new_node(int v,int prio){
	n++;
	tr[n]=reverse_fhq_node<cactus>(0,0,v,1,prio,0);
	return n;
}

template <typename cactus>
void reverse_fhq_treap<cactus>::build_in(int p,int l,int r){
	if(l==r){
		tr[p].v=l;
		tr[p].prio=pt;
		pt++;
		return;
	}
	int mid=(l+r)>>1;
	tr[p].v=mid;
	tr[p].prio=pt;
	pt++;
	if(l<mid){
		tr[p].left=new_node();
		build_in(tr[p].left,l,mid-1);
	}
	if(r>mid){
		tr[p].right=new_node();
		build_in(tr[p].right,mid+1,r);
	}
	resize(p);
}

template <typename cactus>
void reverse_fhq_treap<cactus>::build_a(void){
	n=1;
	pt=0;
	root=1;
	build_in(1,0,num+1);
}

template <typename cactus>
void reverse_fhq_treap<cactus>::init(cactus *p1,cactus *p2){
	num=p2-p1;
	for(int i=1;i<=num;i++){
		a[i]=*p1;
		p1++;
	}
	build_a();
}

template <typename cactus>
void reverse_fhq_treap<cactus>::split_by_size(int p,int sz,int &r1,int &r2){
	if(p==0){
		r1=0;
		r2=0;
		return;
	}
	pushdown(p);
	if(tr[tr[p].left].size<sz){
		r1=p;
		split_by_size(tr[p].right,sz-tr[tr[p].left].size-1,tr[p].right,r2);
	}else{
		r2=p;
		split_by_size(tr[p].left,sz,r1,tr[p].left);
	}
	resize(p);
}

template <typename cactus>
void reverse_fhq_treap<cactus>::merge_in(int &rt,int p1,int p2){
	pushdown(p1);
	pushdown(p2);
	if(p1==0||p2==0){
		rt=p1+p2;
		return;
	}
	if(tr[p1].prio<tr[p2].prio){
		rt=p1;
		merge_in(tr[rt].right,tr[p1].right,p2);
	}else{
		rt=p2;
		merge_in(tr[rt].left,p1,tr[p2].left);
	}
	resize(rt);
}

template <typename cactus>
void reverse_fhq_treap<cactus>::make_tag(int p){
	if(p==0){
		return;
	}
	tr[p].tag^=1;
}

template <typename cactus>
void reverse_fhq_treap<cactus>::pushdown(int p){
	if(tr[p].tag){
		swap_c(tr[p].left,tr[p].right);
		make_tag(tr[p].left);
		make_tag(tr[p].right);
		tr[p].tag=0;
	}
}

template <typename cactus>
void reverse_fhq_treap<cactus>::reverse_in(int pl,int pr){
	int r1,r2,r3;
	split_by_size(root,pl,r1,r2);
	split_by_size(r2,pr-pl+1,r2,r3);
	make_tag(r2);
	merge_in(r2,r2,r3);
	merge_in(root,r1,r2);
}

template <typename cactus>
void reverse_fhq_treap<cactus>::printxroot(int p){
	if(p==0){
		return;
	}
	pushdown(p);
	printxroot(tr[p].left);
	if(tr[p].v>0&&tr[p].v<=num){
		cactusout<<a[tr[p].v]<<space;
	}
	printxroot(tr[p].right);
}

template <typename cactus>
void reverse_fhq_treap<cactus>::renewxroot(int p){
	if(p==0){
		return;
	}
	pushdown(p);
	renew_x_root(tr[p].left);
	if(tr[p].v>0&&tr[p].v<=num){
		r[pt]=a[tr[p].v];
	}
	pt++;
	renew_x_root(tr[p].right);
}

template <typename cactus>
reverse_fhq_treap<cactus>::reverse_fhq_treap(cactus *p1,cactus *p2){
	init(p1,p2);
}

template <typename cactus>
void reverse_fhq_treap<cactus>::reverse(const int pl,const int pr){
	reverse_in(pl,pr);
}

