class complex_c{
	public:
		double a;
		double b;
		complex_c(void);
		complex_c(double a_,double bi_);
		const complex_c conjugate(void);
		void operator=(const double a_);
		const complex_c operator+(const complex_c cplx)const;
		const complex_c operator-(const complex_c cplx)const;
		const complex_c operator*(const complex_c cplx)const;
		const complex_c operator/(const complex_c cplx)const;
		void operator+=(const complex_c cplx);
		void operator-=(const complex_c cplx);
		void operator*=(const complex_c cplx);
		void operator/=(const complex_c cplx);
		const double mod(void);
};

const complex_c operator-(const complex_c cplx){
	return complex_c(-cplx.a,-cplx.b);
}

complex_c::complex_c(void){
	a=0.0;
	b=0.0;
}

complex_c::complex_c(double a_,double bi_){
	a=a_;
	b=bi_;
}

const complex_c complex_c::conjugate(void){
	return complex_c(a,-b);
}

void complex_c::operator=(const double a_){
	a=a_;
	b=0.0;
}

const complex_c complex_c::operator+(const complex_c cplx)const{
	return complex_c(a+cplx.a,b+cplx.b);
}

const complex_c complex_c::operator-(const complex_c cplx)const{
	return complex_c(a-cplx.a,b-cplx.b);
}

const complex_c complex_c::operator*(const complex_c cplx)const{
	return complex_c(a*cplx.a-b*cplx.b,a*cplx.b+b*cplx.a);
}

const complex_c complex_c::operator/(const complex_c cplx)const{
	double cd=cplx.a*cplx.a+cplx.b*cplx.b;
	return complex_c((a*cplx.a+b*cplx.b)/cd,(b*cplx.a-a*cplx.b)/cd);
}

void complex_c::operator+=(const complex_c cplx){
	a+=cplx.a;
	b+=cplx.b;
}

void complex_c::operator-=(const complex_c cplx){
	a-=cplx.a;
	b-=cplx.b;
}

void complex_c::operator*=(const complex_c cplx){
	*this=(*this)*cplx;
}

void complex_c::operator/=(const complex_c cplx){
	*this=(*this)/cplx;
}

const double complex_c::mod(void){
	return sqrt(a*a+b*b);
}

