template <typename cactus>
void persistent_fhq_treap<cactus>::merge_in(int &rt,int p1,int p2){//r1.v<r2.v
	if(p1==0||p2==0){
		rt=copy_node(p1+p2);
		return;
	}
	if(tr[p1].prio<tr[p2].prio){
		rt=copy_node(p1);
		merge_in(tr[rt].right,tr[p1].right,p2);
	}else{
		rt=copy_node(p2);
		merge_in(tr[rt].left,p1,tr[p2].left);
	}
	resize(rt);
}

template <typename cactus>
void persistent_fhq_treap<cactus>::split_by_value(int r,cactus val,int &p1,int &p2){//tree of p1 includes val
	if(r==0){
		p1=0;
		p2=0;
		return;
	}
	if(tr[r].v<=val){
		p1=copy_node(r);
		split_by_value(tr[r].right,val,tr[p1].right,p2);
		resize(p1);
	}else{
		p2=copy_node(r);
		split_by_value(tr[r].left,val,p1,tr[p2].left);
		resize(p2);
	}
}

