template <typename cactus>
void persistent_fhq_treap<cactus>::insert_in(cactus v,int version){
	if(root[version]==0){
		root[num]=new_node(0,0,v,1,rand_c());
		num++;
		return;
	}
	int r1,r2,r3;
	split_by_value(root[version],v-1,r1,r2);
	split_by_value(r2,v,r2,r3);
	if(r2==0){
		merge_in(r2,new_node(0,0,v,1,rand_c()),r3);
		merge_in(root[num],r1,r2);
		num++;
	}else{
		merge_in(r2,r2,r3);
		merge_in(root[num],r1,r2);
		num++;
	}
}

template <typename cactus>
void persistent_fhq_treap<cactus>::del_in(cactus v,int version){
	if(root[version]==0||tr[root[version]].size==1){
		root[num]=0;
		num++;
		return;
	}
	int r1,r2,r3;
	split_by_value(root[version],v-1,r1,r2);
	split_by_value(r2,v,r2,r3);
	if(r2==0){
		merge_in(root[num],r1,r3);
		num++;
	}else{
		release_empty(r2);
		merge_in(root[num],r1,r3);
		num++;
	}
}

template <typename cactus>
cactus persistent_fhq_treap<cactus>::kth_in(int k,int version){
	int r1,r2,r3;
	split_by_size(root[version],k-1,r1,r2);
	split_by_size(r2,1,r2,r3);
	int rt=r2;
	merge_in(r2,r2,r3);
	merge_in(root[num],r1,r2);
	num++;
	return tr[rt].v;
}

template <typename cactus>
int persistent_fhq_treap<cactus>::rankin(cactus v,int version){
	int r1,r2;
	split_by_value(root[version],v-1,r1,r2);
	if(r2==0){
		merge_in(root[num],r1,r2);
		num++;
		return INF;
	}else{
		int rt=tr[r1].size;
		merge_in(root[num],r1,r2);
		num++;
		return rt+1;
	}
}

template <typename cactus>
cactus persistent_fhq_treap<cactus>::suc_in(cactus v,int version){
	int r1,r2;
	split_by_value(root[version],v,r1,r2);
	int vr;
	if(r2==0){
		vr=INF;
	}else{
		vr=get_min_in(r2);
	}
	merge_in(root[num],r1,r2);
	return vr;
}

