template <typename cactus>
void persistent_multi_fhq_treap<cactus>::insert_in(cactus v,int version){
	if(root[version]==0){
		root[num]=new_node(0,0,v,1,rand_c());
		num++;
		return;
	}
	int r1,r2,r3;
	split_by_value(root[version],v-1,r1,r2);
	split_by_value(r2,v,r2,r3);
	if(r2==0){
		merge_in(r2,new_node(0,0,v,1,rand_c()),r3);
		merge_in(root[num],r1,r2);
		num++;
	}else{
		tr[r2].cnt++;
		tr[r2].size++;
		merge_in(r2,r2,r3);
		merge_in(root[num],r1,r2);
		num++;
	}
}

template <typename cactus>
void persistent_multi_fhq_treap<cactus>::del_in(cactus v,int version){
	if(root[version]==0||tr[root[version]].size==1){
		root[num]=0;
		num++;
		return;
	}
	int r1,r2,r3;
	split_by_value(root[version],v-1,r1,r2);
	split_by_value(r2,v,r2,r3);
	if(r2==0){
		merge_in(root[num],r1,r3);
		num++;
	}else{
		if(tr[r2].cnt>1){
			tr[r2].cnt--;
			merge_in(r2,r2,r3);
			merge_in(root[num],r1,r2);
			num++;
		}else{
			release_empty(r2);
			merge_in(root[num],r1,r3);
			num++;
		}

	}
}

template <typename cactus>
cactus persistent_multi_fhq_treap<cactus>::kthinroot(int r,int k){
	if(tr[r].left==0){
		if(k<=tr[r].cnt){
			return tr[r].v;
		}else{
			return kthinroot(tr[r].right,k-tr[r].cnt);
		}
	}else{
		if(k<=tr[tr[r].left].size){
			return kthinroot(tr[r].left,k);
		}else{
			if(k>tr[tr[r].left].size+tr[r].cnt){
				return kthinroot(tr[r].right,k-tr[r].cnt-tr[tr[r].left].size);
			}else{
				return tr[r].v;
			}
		}
	}
}

