template <typename cactus>
class persistent_reverse_fhq_treap{
	private:
		persistent_reverse_fhq_node<cactus> tr[MAXN];
		int n;
		int root[MAXNUM];
		int rn;
		int pt;
		cactus a[MAXNUM];
		cactus r[MAXNUM];
		int num;
		int new_node(void);
		int new_node(int v,int pr);
		int copy_node(int p);
		void build0(int p,int l,int r);
		void build_in(void);
		void resize(int p);
		void maketag(int p);
		void pushdown(int p);
		void split_by_size(int r,int sz,int &p1,int &p2);
		void merge_in(int &r,int p1,int p2);
		void reverse_in(int version,int pl,int pr);
		void printxroot(int p);
		void getxroot(int p);
		void print_in(int version);
		cactus* get_in(int version);
	public:
		explicit persistent_reverse_fhq_treap(cactus *a1,cactus *a2);
		const SIZE_C size(void);
		void reverse(const int version,const int pl,const int pr);
		void simple_reverse(const int pl,const int pr);
		void print(const int version);
		void simple_print(void);
		cactus* get(const int version);
		cactus* simple_get(void);
};

template <typename cactus>
const SIZE_C persistent_reverse_fhq_treap<cactus>::size(void){
	return num;
}

template <typename cactus>
int persistent_reverse_fhq_treap<cactus>::new_node(void){
	n++;
	return n;
}

template <typename cactus>
int persistent_reverse_fhq_treap<cactus>::new_node(int v,int pr){
	n++;
	tr[n]=persistent_reverse_fhq_node<cactus> (0,0,v,0,pr,1);
	return n;
}

template <typename cactus>
int persistent_reverse_fhq_treap<cactus>::copy_node(int p){
	if(p==0){
		return 0;
	}
	n++;
	tr[n]=tr[p];
	return n;
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::resize(int p){
	tr[p].size=tr[tr[p].left].size+tr[tr[p].right].size+1;
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::maketag(int p){
	if(p==0){
		return;
	}
	tr[p].tag^=1;
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::pushdown(int p){
	if(tr[p].tag){
		tr[p].tag=0;
		if(tr[p].left){
			tr[p].left=copy_node(tr[p].left);
		}
		if(tr[p].right){
			tr[p].right=copy_node(tr[p].right);
		}
		swap_c(tr[p].left,tr[p].right);
		maketag(tr[p].left);
		maketag(tr[p].right);
	}
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::build0(int p,int l,int r){
	if(l==r){
		tr[p].v=l;
		tr[p].prio=pt;
		pt++;
		return;
	}
	tr[p].prio=pt;
	pt++;
	int mid=(l+r)>>1;
	tr[p].v=mid;
	if(l<mid){
		tr[p].left=new_node();
		build0(tr[p].left,l,mid-1);
	}
	if(r>mid){
		tr[p].right=new_node();
		build0(tr[p].right,mid+1,r);
	}
	resize(p);
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::build_in(void){
	n=1;
	build0(1,0,num+1);
	rn=1;
	root[0]=1;
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::split_by_size(int r,int sz,int &p1,int &p2){
	pushdown(r);
	if(r==0){
		p1=0;
		p2=0;
		return;
	}
	if(sz<=tr[tr[r].left].size){
		p2=copy_node(r);
		split_by_size(tr[r].left,sz,p1,tr[p2].left);
		resize(p2);
	}else{
		p1=copy_node(r);
		split_by_size(tr[r].right,sz-tr[tr[r].left].size-1,tr[p1].right,p2);
		resize(p1);
	}
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::merge_in(int &r,int p1,int p2){
	pushdown(p1);
	pushdown(p2);
	if(p1==0||p2==0){
		r=copy_node(p1+p2);
		return;
	}
	if(tr[p1].prio<tr[p2].prio){
		r=copy_node(p1);
		merge_in(tr[r].right,tr[p1].right,p2);
	}else{
		r=copy_node(p2);
		merge_in(tr[r].left,p1,tr[p2].left);
	}
	resize(r);
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::reverse_in(int version,int pl,int pr){
	int r1,r2,r3;
	split_by_size(root[version],pl,r1,r2);
	split_by_size(r2,pr-pl+1,r2,r3);
	maketag(r2);
	merge_in(r2,r2,r3);
	merge_in(root[rn],r1,r2);
	rn++;
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::printxroot(int p){
	if(p==0){
		return;
	}
	pushdown(p);
	printxroot(tr[p].left);
	cactusout<<a[tr[p].v]<<space;
	printxroot(tr[p].right);
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::getxroot(int p){
	if(p==0){
		return;
	}
	pushdown(p);
	getxroot(tr[p].left);
	r[pt]=a[tr[p].v];
	pt++;
	getxroot(tr[p].right);
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::print_in(int version){
	printxroot(root[version]);
	cactusout<<enter;
}

template <typename cactus>
cactus* persistent_reverse_fhq_treap<cactus>::get_in(int version){
	pt=1;
	getxroot(root[version]);
	return r+1;
}

template <typename cactus>
persistent_reverse_fhq_treap<cactus>::persistent_reverse_fhq_treap(cactus *a1,cactus *a2){
	n=0;
	tr[0]=persistent_reverse_fhq_node<cactus> (0,0,0,0,0,0);
	num=a2-a1;
	for(int i=1;i<=num;i++){
		a[i]=*a1;
		a1++;
	}
	pt=0;
	build_in();
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::reverse(const int version,const int pl,const int pr){
	reverse_in(version,pl,pr);
}

template <typename cactus>
void persistent_reverse_fhq_treap<cactus>::simple_reverse(const int pl,const int pr){
	reverse_in(rn-1,pl,pr);
}

