};

range_node::range_node(void){
	left=0;
	right=0;
	v=0;
}

range_node::range_node(int l,int r,int val){
	left=l;
	right=r;
	v=val;
}



class range_weighed_tree{
	private:
		int n;
		range_node tr[MAXN];
		int num;
		int root[MAXNUM];
		int value_range;
		int a[MAXNUM];
		int c[MAXNUM];
		int teml[MAXNUM];
		int temln;
		int temr[MAXNUM];
		int temrn;
		int new_node(void);
		int new_node(int v);
		void buildin_empty(int p,int l,int r);
		void build_empty(void);
		void buildin_a(int p,int l,int r,int v);
		void build_a(void);
		void add_single(int k,int l,int r,int p,int v);
		int query_single(int k,int l,int r,int p);
		int range_query_single(int k,int l,int r,int pl,int pr);
		int kthonpos(int p,int l,int r,int k);
		void add_in(const int delta,const int p);
		void minus_in(const int delta,const int p);
		void replace_in(const int value,const int p);
		int find_in(const int value,const int pl,const int pr);
		int rank_in(const int v,const int pl,const int pr);
		int kth_in(int k,const int pl,const int pr);
		int pre_in(const int v,const int pl,const int pr);
		int suc_in(const int v,const int pl,const int pr);
	public:
		range_weighed_tree(void);
		range_weighed_tree(const int valuerange,const int length);
		range_weighed_tree(int *a1,int *a2);
		range_weighed_tree(int *a1,int *a2,const int valuerange);
		const SIZE_C size(void);
		const SIZE_C size(const int pl,const int pr);
		const SIZE_C valuerange(void);
		void add(const int delta,const int p);
		void minus(const int delta,const int p);
		void replace(const int val,const int p);
		const int find(const int value,const int pl,const int pr);
		const int rank(const int v,const int pl,const int pr);
		const int kth(const int k,const int pl,const int pr);
		const int pre(const int v,const int pl,const int pr);
		const int suc(const int v,const int pl,const int pr);
};

const SIZE_C range_weighed_tree::size(void){
	return num;
}

const SIZE_C range_weighed_tree::size(const int pl,const int pr){
	int rl=0,rr=0;
	int plx=pl,prx=pr;
	plx--;
	while(plx){
		rl+=tr[root[plx]].v;
		plx-=lowbit(plx);
	}
	while(prx){
		rr+=tr[root[prx]].v;
		prx-=lowbit(prx);
	}
	return rr-rl;
}

const SIZE_C range_weighed_tree::valuerange(void){
	return value_range;
}

int range_weighed_tree::new_node(void){
	n++;
	return n;
}

int range_weighed_tree::new_node(int v){
	n++;
	tr[n].v=v;
	return n;
}

void range_weighed_tree::buildin_empty(int p,int l,int r){
	if(l==r){
		return;
	}
	tr[p].left=new_node();
	tr[p].right=new_node();
	int mid=(l+r)>>1;
	buildin_empty(tr[p].left,l,mid);
	buildin_empty(tr[p].right,mid+1,r);
}

void range_weighed_tree::build_empty(void){
	for(int i=1;i<=num;i++){
		root[i]=new_node();
		buildin_empty(root[i],1,value_range);
	}
}

void range_weighed_tree::buildin_a(int p,int l,int r,int v){
	tr[p].v++;
	if(l==r){
		return;
	}
	int mid=(l+r)>>1;
	if(v>mid){
		buildin_a(tr[p].right,mid+1,r,v);
	}else{
		buildin_a(tr[p].left,l,mid,v);
	}
}

void range_weighed_tree::build_a(void){
	build_empty();
	int p;
	for(int i=1;i<=num;i++){
		p=i;
		while(p<=num){
			buildin_a(root[p],1,value_range,a[i]);
			p+=lowbit(p);
		}
	}
}

void range_weighed_tree::add_single(int k,int l,int r,int p,int v){
	if(l==r){
		tr[k].v+=v;
		return;
	}
	int mid=(l+r)>>1;
	tr[k].v+=v;
	if(p>mid){
		add_single(tr[k].right,mid+1,r,p,v);
	}else{
		add_single(tr[k].left,l,mid,p,v);
	}
}

int range_weighed_tree::query_single(int k,int l,int r,int p){
	if(l==r){
		return tr[k].v;
	}
	int mid=(l+r)>>1;
	if(p>mid){
		return query_single(tr[k].right,mid+1,r,p);
	}else{
		return query_single(tr[k].left,l,mid,p);
	}
}

int range_weighed_tree::range_query_single(int k,int l,int r,int pl,int pr){
	if(inrange(l,r,pl,pr)){
		return tr[k].v;
	}
	if(outofrange(l,r,pl,pr)){
		return 0;
	}
	int mid=(l+r)>>1;
	return range_query_single(tr[k].left,l,mid,pl,pr)+range_query_single(tr[k].right,mid+1,r,pl,pr);
}

int range_weighed_tree::kthonpos(int p,int l,int r,int k){
	if(l==r){
		return l;
	}
	int mid=(l+r)>>1;
	if(k<=tr[tr[p].left].v){
		return kthonpos(tr[p].left,l,mid,k);
	}else{
		return kthonpos(tr[p].right,mid+1,r,k-tr[tr[p].left].v);
	}
}

void range_weighed_tree::add_in(const int delta,const int p){
	int px=p;
	while(px<=num){
		add_single(root[px],1,value_range,a[p],-1);
		px+=lowbit(px);
	}
	px=p;
	a[p]+=delta;
	while(px<=num){
		add_single(root[px],1,value_range,a[p],1);
		px+=lowbit(px);
	}
}

void range_weighed_tree::minus_in(const int delta,const int p){
	int px=p;
	while(px<=num){
		add_single(root[px],1,value_range,a[p],-1);
		px+=lowbit(px);
	}
	px=p;
	a[p]-=delta;
	while(px<=num){
		add_single(root[px],1,value_range,a[p],1);
		px+=lowbit(px);
	}
}

void range_weighed_tree::replace_in(const int value,const int p){
	int px=p;
	while(px<=num){
		add_single(root[px],1,value_range,a[p],-1);
		px+=lowbit(px);
	}
	px=p;
	a[p]=value;
	while(px<=num){
		add_single(root[px],1,value_range,a[p],1);
		px+=lowbit(px);
	}
}

int range_weighed_tree::find_in(const int value,const int pl,const int pr){
	int s1=0,s2=0;
	int plx=pl-1,prx=pr;
	while(plx){
		s1+=query_single(root[plx],1,value_range,value);
		plx-=lowbit(plx);
	}
	while(prx){
		s2+=query_single(root[prx],1,value_range,value);
		prx-=lowbit(prx);
	}
	return s2-s1;
}

int range_weighed_tree::rank_in(const int v,const int pl,const int pr){
	if(v==1){
		return 1;
	}
	int r1=0,r2=0;
	int plx=pl-1,prx=pr;
	while(plx){
		r1+=range_query_single(root[plx],1,value_range,1,v-1);
		plx-=lowbit(plx);
	}
	while(prx){
		r2+=range_query_single(root[prx],1,value_range,1,v-1);
		prx-=lowbit(prx);
	}
	return r2-r1+1;
}

int range_weighed_tree::kth_in(int k,const int pl,const int pr){
	temln=0;
	temrn=0;
	int plx=pl-1;
	int prx=pr;
	while(plx){
		teml[temln]=root[plx];
		temln++;
		plx-=lowbit(plx);
	}
	while(prx){
		temr[temrn]=root[prx];
		temrn++;
		prx-=lowbit(prx);
	}
	int l,r,mid,s=0;
	l=1;
	r=value_range;
	while(1){
		if(l==r){
			return l;
		}
		s=0;
		mid=(l+r)>>1;
		for(int i=0;i<temrn;i++){
			s+=tr[tr[temr[i]].left].v;
		}
		for(int i=0;i<temln;i++){
			s-=tr[tr[teml[i]].left].v;
		}
		if(k<=s){
			for(int i=0;i<temrn;i++){
				temr[i]=tr[temr[i]].left;
			}
			for(int i=0;i<temln;i++){
				teml[i]=tr[teml[i]].left;
			}
			r=mid;
		}else{
			for(int i=0;i<temrn;i++){
				temr[i]=tr[temr[i]].right;
			}
			for(int i=0;i<temln;i++){
				teml[i]=tr[teml[i]].right;
			}
			l=mid+1;
			k-=s;
		}
	}
}

int range_weighed_tree::pre_in(const int v,const int pl,const int pr){
	int rk=rank_in(v,pl,pr);
	if(rk==1){
		return -INF;
	}
	else{
		return kth_in(rk-1,pl,pr);
	}
}

int range_weighed_tree::suc_in(const int v,const int pl,const int pr){
	int rk=rank_in(v,pl,pr);
	int tot=find_in(v,pl,pr);
	if(rk==pr-pl+1||rk+tot-1>=pr-pl+1){
		return INF;
	}
	else{
		return kth_in(rk+tot,pl,pr);
	}
}

range_weighed_tree::range_weighed_tree(void){
	n=0;
	value_range=MAXNUM;
	num=MAXNUM;
	build_empty();
}

range_weighed_tree::range_weighed_tree(const int valuerange,const int length){
	n=0;
	value_range=valuerange;
	num=length;
	build_empty();
}

range_weighed_tree::range_weighed_tree(int *a1,int *a2){
	n=0;
	num=a2-a1;
	value_range=0;
	for(int i=1;i<=num;i++){
		a[i]=*a1;
		a1++;
		if(a[i]>value_range){
			value_range=a[i];
		}
	}
	build_a();
}

range_weighed_tree::range_weighed_tree(int *a1,int *a2,const int valuerange){
	n=0;
	num=a2-a1;
	value_range=valuerange;
	for(int i=1;i<=num;i++){
		a[i]=*a1;
		a1++;
		if(a[i]>value_range){
			value_range=a[i];
		}
	}
	build_a();
}

void range_weighed_tree::add(const int delta,const int p){
	add_in(delta,p);
}

void range_weighed_tree::replace(const int val,const int p){
	replace_in(val,p);
}

void range_weighed_tree::minus(const int delta,const int p){
	minus_in(delta,p);
}

const int range_weighed_tree::rank(const int v,const int pl,const int pr){
	return rank_in(v,pl,pr);
}

const int range_weighed_tree::find(const int value,const int pl,const int pr){
	return find_in(value,pl,pr);
}

const int range_weighed_tree::kth(const int k,const int pl,const int pr){
	return kth_in(k,pl,pr);
}

const int range_weighed_tree::pre(const int v,const int pl,const int pr){
	return pre_in(v,pl,pr);
}

const int range_weighed_tree::suc(const int v,const int pl,const int pr){
	return suc_in(v,pl,pr);
}

