template <typename cactus>
class range_fhq_node{
	friend class range_fhq_treap<cactus>;
	private:
		int left;
		int right;
		cactus v;
		int cnt;
		int size;
		int priority;
		range_fhq_node(void);
		range_fhq_node(const cactus val);
		range_fhq_node(int l,int r,cactus val,int num,int sz,int prio);
};

template <typename cactus>
range_fhq_node<cactus>::range_fhq_node(void){
	left=0;
	right=0;
	cnt=0;
	size=0;
	priority=0;
}

template <typename cactus>
range_fhq_node<cactus>::range_fhq_node(const cactus val){
	left=0;
	right=0;
	cnt=1;
	size=1;
	v=val;
	priority=0;
}

template <typename cactus>
range_fhq_node<cactus>::range_fhq_node(int l,int r,cactus val,int num,int sz,int prio){
	left=l;
	right=r;
	cnt=num;
	size=1;
	v=val;
	priority=prio;
}



template <typename cactus>
class range_fhq_treap{
	private:
		int n;
		range_fhq_node<cactus> tr[MAXN];
		int a[MAXNUM];
		int num;
		int root[MAXNUM];
		int em[MAXN];
		int emn;
		int seed=311519;
		cactus maxx=-INF;
		cactus minx=INF;
		inline const int rand_c(void){return seed=(int)((seed*4827153LL+114514)%2147483647);}
		int new_node(void);
		int new_node(cactus v);
		void resize(int p);
		void merge_in(int &r,int p1,int p2);
		void split_by_size(int r,int sz,int &p1,int &p2);
		void split_by_value(int r,cactus v,int &p1,int &p2);
		cactus max_single(int p);
		cactus min_single(int p);
		int rank_single(int nx,cactus v);
		int single_tot(int nx,cactus v);
		int query_tot(int pl,int pr,cactus v);
		void replace_single(int nx,int v1,int v2);
		void build_single(int p,cactus v);
		void build_in(void);
		void init(cactus *a1,cactus *a2);
		void replace_in(int p,cactus value);
		void add_in(int p,cactus delta);
		void minus_in(int p,cactus delta);
		int rank_in(int pl,int pr,cactus value);
		cactus kth_in(int pl,int pr,int k);
		cactus pre_in(int pl,int pr,cactus val);
		cactus suc_in(int pl,int pr,cactus val);
		cactus max_in(int pl,int pr);
		cactus min_in(int pl,int pr);
	public:
		explicit range_fhq_treap(cactus *a1,cactus *a2);
		const SIZE_C size(void);
		const SIZE_C size(const int pl,const int pr);
		void replace(const int p,const cactus value);
		void add(const int p,const cactus delta);
		void minus(const int p,const cactus delta);
		const int rank(const int pl,const int pr,const cactus value);
		const cactus kth(const int pl,const int pr,const int k);
		const cactus pre(const int pl,const int pr,const cactus value);
		const cactus suc(const int pl,const int pr,const cactus value);
		const cactus max(const int pl,const int pr);
		const cactus min(const int pl,const int pr);
};

template <typename cactus>
const SIZE_C range_fhq_treap<cactus>::size(void){
	return num;
}

template <typename cactus>
const SIZE_C range_fhq_treap<cactus>::size(const int pl,const int pr){
	int rl=0,rr=0;
	int plx=pl,prx=pr;
	plx--;
	while(plx){
		rl+=tr[root[plx]].size;
		plx-=lowbit(plx);
	}
	while(prx){
		rr+=tr[root[prx]].size;
		prx-=lowbit(prx);
	}
	return rr-rl;
}

template <typename cactus>
int range_fhq_treap<cactus>::new_node(void){
	if(emn){
		tr[em[emn-1]]=range_fhq_node<cactus>();
		emn--;
		return em[emn];
	}else{
		n++;
		return n;
	}
}

template <typename cactus>
int range_fhq_treap<cactus>::new_node(cactus v){
	if(emn){
		tr[em[emn-1]]=range_fhq_node<cactus>(0,0,v,1,1,rand_c());
		emn--;
		return em[emn];
	}else{
		n++;
		tr[n]=range_fhq_node<cactus>(0,0,v,1,1,rand_c());
		return n;
	}
}

template <typename cactus>
void range_fhq_treap<cactus>::resize(int p){
	tr[p].size=tr[p].cnt+tr[tr[p].left].size+tr[tr[p].right].size;
}

template <typename cactus>
void range_fhq_treap<cactus>::merge_in(int &r,int p1,int p2){
	if(p1==0||p2==0){
		r=p1+p2;
		return;
	}
	if(tr[p1].priority<tr[p2].priority){
		r=p1;
		merge_in(tr[r].right,tr[p1].right,p2);
	}else{
		r=p2;
		merge_in(tr[r].left,p1,tr[p2].left);
	}
	resize(r);
}

template <typename cactus>
void range_fhq_treap<cactus>::split_by_size(int r,int sz,int &p1,int &p2){
	//the algorithm makes sure that the sz_th element falls in p1
	if(r==0){
		p1=0;
		p2=0;
		return;
	}
	if(tr[tr[r].left].size+tr[r].cnt>=sz){
		p1=r;
		split_by_size(tr[r].right,sz-tr[tr[r].left].size-tr[r].cnt,tr[p1].right,p2);
		resize(p1);
	}else{
		p2=r;
		split_by_size(tr[r].left,sz,p1,tr[p2].left);
		resize(p2);
	}
}

template <typename cactus>
void range_fhq_treap<cactus>::split_by_value(int r,cactus v,int &p1,int &p2){
	if(r==0){
		p1=0;
		p2=0;
		return;
	}
	if(tr[r].v<=v){
		p1=r;
		split_by_value(tr[r].right,v,tr[p1].right,p2);
		resize(p1);
	}else{
		p2=r;
		split_by_value(tr[r].left,v,p1,tr[p2].left);
		resize(p2);
	}
}

template <typename cactus>
cactus range_fhq_treap<cactus>::max_single(int p){
	if(tr[p].right==0){
		return tr[p].v;
	}
	return max_single(tr[p].right);
}

template <typename cactus>
cactus range_fhq_treap<cactus>::min_single(int p){
	if(tr[p].left==0){
		return tr[p].v;
	}
	return max_single(tr[p].left);
}

template <typename cactus>
int range_fhq_treap<cactus>::rank_single(int nx,cactus v){//minused by 1
	int r1=0,r2=0;
	split_by_value(root[nx],v-1,r1,r2);
	int ret=tr[r1].size;
	merge_in(root[nx],r1,r2);
	return ret;
}

template <typename cactus>
int range_fhq_treap<cactus>::single_tot(int nx,cactus v){
	int r1,r2,r3;
	split_by_value(root[nx],v-1,r1,r2);
	split_by_value(r2,v,r2,r3);
	int rt=0;
	if(r2){
		rt=tr[r2].size;
		merge_in(r2,r2,r3);
		merge_in(root[nx],r1,r2);
	}else{
		merge_in(root[nx],r1,r3);
	}
	return rt;
}

template <typename cactus>
int range_fhq_treap<cactus>::query_tot(int pl,int pr,cactus v){
	int v1=0,v2=0;
	pl--;
	while(pl){
		v1+=single_tot(pl,v);
		pl-=lowbit(pl);
	}
	while(pr){
		v2+=single_tot(pr,v);
		pr-=lowbit(pr);
	}
	return v2-v1;
}

template <typename cactus>
void range_fhq_treap<cactus>::replace_single(int nx,int v1,int v2){
	int r1=0,r2=0,r3=0;
	split_by_value(root[nx],v1-1,r1,r2);
	split_by_value(r2,v1,r2,r3);
	if(r2==0){
		merge_in(root[nx],r1,r3);
		return;
	}else{
		if(tr[r2].cnt>1){
			tr[r2].cnt--;
			tr[r2].size--;
			merge_in(r2,r2,r3);
			merge_in(root[nx],r1,r2);
		}else{
			em[emn]=r2;
			emn++;
			merge_in(root[nx],r1,r3);
		}
	}
	r1=0,r2=0,r3=0;
	split_by_value(root[nx],v2-1,r1,r2);
	split_by_value(r2,v2,r2,r3);
	if(r2==0){
		r2=new_node(v2);
		merge_in(r2,r2,r3);
		merge_in(root[nx],r1,r2);
		return;
	}else{
		tr[r2].cnt++;
		tr[r2].size++;
		merge_in(r2,r2,r3);
		merge_in(root[nx],r1,r2);
		return;
	}
}

template <typename cactus>
void range_fhq_treap<cactus>::build_single(int p,cactus v){
	if(root[p]==0){
		root[p]=new_node(v);
		return;
	}
	int r1=0,r2=0,r3=0;
	split_by_value(root[p],v-1,r1,r2);
	split_by_value(r2,v,r2,r3);
	if(r2==0){
		r2=new_node(v);
		merge_in(r2,r2,r3);
		merge_in(root[p],r1,r2);
	}else{
		tr[r2].cnt++;
		tr[r2].size++;
		merge_in(r2,r2,r3);
		merge_in(root[p],r1,r2);
	}
}

template <typename cactus>
void range_fhq_treap<cactus>::build_in(void){
	int px;
	for(int i=1;i<=num;i++){
		px=i;
		while(px<=num){
			build_single(px,a[i]);
			px+=lowbit(px);
		}
	}
}

template <typename cactus>
void range_fhq_treap<cactus>::init(cactus *a1,cactus *a2){
	tr[0].cnt=0;
	tr[0].size=0;
	num=a2-a1;
	emn=0;
	for(int i=1;i<=num;i++){
		a[i]=*a1;
		if(maxx<a[i]){
			maxx=a[i];
		}
		if(minx>a[i]){
			minx=a[i];
		}
		a1++;
		root[i]=0;
	}
	build_in();
}

template <typename cactus>
void range_fhq_treap<cactus>::replace_in(int p,cactus value){
	if(maxx<value){
		maxx=value;
	}
	if(minx>value){
		minx=value;
	}
	int px=p;
	while(px<=num){
		replace_single(px,a[p],value);
		px+=lowbit(px);
	}
	a[p]=value;
}

template <typename cactus>
void range_fhq_treap<cactus>::add_in(int p,cactus delta){
	replace_in(p,a[p]+delta);
}

template <typename cactus>
void range_fhq_treap<cactus>::minus_in(int p,cactus delta){
	replace_in(p,a[p]-delta);
}

template <typename cactus>
int range_fhq_treap<cactus>::rank_in(int pl,int pr,cactus value){
	int rl=0,rr=0;
	pl--;
	while(pl){
		rl+=rank_single(pl,value);
		pl-=lowbit(pl);
	}
	while(pr){
		rr+=rank_single(pr,value);
		pr-=lowbit(pr);
	}
	return rr-rl+1;
}

template <typename cactus>
cactus range_fhq_treap<cactus>::kth_in(int pl,int pr,int k){
	if(k<1){
		return -INF;
	}
	if(k>(pr-pl+1)){
		return INF;
	}
	cactus l=minx,r=maxx;
	while(l<r){
		int mid=(l+r+1)>>1;
		if(rank_in(pl,pr,mid)>k){
			r=mid-1;
		}else{
			l=mid;
		}
	}
	return r;
}

template <typename cactus>
cactus range_fhq_treap<cactus>::pre_in(int pl,int pr,cactus val){
	return kth_in(pl,pr,rank_in(pl,pr,val)-1);
}

template <typename cactus>
cactus range_fhq_treap<cactus>::suc_in(int pl,int pr,cactus val){
	return kth_in(pl,pr,rank_in(pl,pr,val)+query_tot(pl,pr,val));
}

template <typename cactus>
cactus range_fhq_treap<cactus>::max_in(int pl,int pr){
	return kth_in(pl,pr,pr-pl+1);
}

template <typename cactus>
cactus range_fhq_treap<cactus>::min_in(int pl,int pr){
	return kth_in(pl,pr,pr-pl+1);
}

template <typename cactus>
range_fhq_treap<cactus>::range_fhq_treap(cactus *a1,cactus *a2){
	init(a1,a2);
}

template <typename cactus>
void range_fhq_treap<cactus>::replace(const int p,const cactus value){
	replace_in(p,value);
}

template <typename cactus>
void range_fhq_treap<cactus>::add(const int p,const cactus delta){
	add_in(p,delta);
}

template <typename cactus>
void range_fhq_treap<cactus>::minus(const int p,const cactus delta){
	minus_in(p,delta);
}

template <typename cactus>
const int range_fhq_treap<cactus>::rank(const int pl,const int pr,const cactus value){
	return rank_in(pl,pr,value);
}

template <typename cactus>
const cactus range_fhq_treap<cactus>::kth(const int pl,const int pr,const int k){
	return kth_in(pl,pr,k);
}

template <typename cactus>
const cactus range_fhq_treap<cactus>::pre(const int pl,const int pr,const cactus value){
	return pre_in(pl,pr,value);
}

template <typename cactus>
const cactus range_fhq_treap<cactus>::suc(const int pl,const int pr,const cactus value){
	return suc_in(pl,pr,value);
}

template <typename cactus>
const cactus range_fhq_treap<cactus>::max(const int pl,const int pr){
	return max_in(pl,pr);
}

template <typename cactus>
const cactus range_fhq_treap<cactus>::min(const int pl,const int pr){
	return min_in(pl,pr);
}

