template <typename cactus>
class leftist_node{
	friend class min_leftist_tree <cactus>;
	friend class max_leftist_tree <cactus>;
	private:
		int left;
		int right;
		int rt;
		int dist;
		int id;
		cactus v;
		leftist_node(void);
		leftist_node(int l,int r,int root,int dis,int id_,cactus value);
		const bool operator>(leftist_node b);
		const bool operator<(leftist_node b);
};

template <typename cactus>
leftist_node<cactus>::leftist_node(void){
	left=0;
	right=0;
	rt=0;
	dist=-1;
	id=0;
}

template <typename cactus>
leftist_node<cactus>::leftist_node(int l,int r,int root,int dis,int id_,cactus value){
	left=l;
	right=r;
	rt=root;
	dist=dis;
	id=id_;
	v=value;
}

template <typename cactus>
const bool leftist_node<cactus>::operator>(leftist_node b){
	if(v==b.v){
		return id>b.id;
	}else{
		return v>b.v;
	}
}

template <typename cactus>
const bool leftist_node<cactus>::operator<(leftist_node b){
	if(v==b.v){
		return id<b.id;
	}else{
		return v<b.v;
	}
}



template <typename cactus>
class min_leftist_tree{
	private:
		int n;
		int timer;
		leftist_node <cactus> tr[MAXNUM];
		int new_node(int l,int r,int root,int dis,int id_,cactus value);
		void init(cactus *a1,cactus *a2);
		int get_root(int p);
		void merge_inline(int &r,int p1,int p2);
		void re_dis(int p);
		bool merge_in(int p1,int p2);
		int insert_in(cactus v,int p);
		void del_in(int p);
		cactus min_in(int p);
	public:
		explicit min_leftist_tree(cactus *a1,cactus *a2);
		const SIZE_C size(void);
		const bool merge(const int p1,const int p2);
		const int insert(const cactus v,const int p);
		const int root(const int p);
		void del(const int p);
		const cactus value(const int p);
		const cactus min(const int p);
};

template <typename cactus>
int min_leftist_tree<cactus>::new_node(int l,int r,int root,int dis,int id_,cactus value){
	n++;
	tr[n]=leftist_node <cactus> (l,r,root,dis,id_,value);
	return n;
}

template <typename cactus>
void min_leftist_tree<cactus>::init(cactus *a1,cactus *a2){
	n=0;
	int num=a2-a1;
	for(int i=1;i<=num;i++){
		new_node(0,0,i,-1,i,*a1);
		a1++;
	}
	timer=num+1;
}

template <typename cactus>
int min_leftist_tree<cactus>::get_root(int p){
	if(tr[p].rt==p){
		return p;
	}else{
		return (tr[p].rt=get_root(tr[p].rt));
	}
}

template <typename cactus>
void min_leftist_tree<cactus>::merge_inline(int &r,int p1,int p2){
	if(p1==0||p2==0){
		if(p1){
			tr[p1].rt=p1;
		}
		if(p2){
			tr[p2].rt=p2;
		}
		r=p1+p2;
		re_dis(r);
		return;
	}
	if(tr[p1]>tr[p2]){
		swap_c(p1,p2);
	}
	tr[p2].rt=p1;
	r=p1;
	merge_inline(tr[r].right,tr[p1].right,p2);
	tr[tr[p1].right].rt=p1;
	re_dis(r);
}

template <typename cactus>
void min_leftist_tree<cactus>::re_dis(int p){
	if(p<1){
		return;
	}
	int disl,disr;
	if(tr[p].left==0){
		disl=-1;
	}else{
		disl=tr[tr[p].left].dist+1;
	}
	if(tr[p].right==0){
		disr=-1;
	}else{
		disr=tr[tr[p].right].dist+1;
	}
	if(disl<disr){
		swap_c(tr[p].left,tr[p].right);
		tr[p].dist=disl;
	}else{
		tr[p].dist=disr;
	}
}

template <typename cactus>
bool min_leftist_tree<cactus>::merge_in(int p1,int p2){
	int r;
	p1=get_root(p1);
	p2=get_root(p2);
	if(p1==p2){
		return 0;
	}
	merge_inline(r,p1,p2);
	return 1;
}

template <typename cactus>
int min_leftist_tree<cactus>::insert_in(cactus v,int p){
	int ret=new_node(0,0,0,-1,timer,v);
	tr[ret].rt=ret;
	merge_in(ret,p);
	return ret;
}

template <typename cactus>
void min_leftist_tree<cactus>::del_in(int p){
	p=get_root(p);
	tr[tr[p].right].rt=tr[p].right;
	tr[tr[p].left].rt=tr[p].left;
	merge_inline(tr[p].rt,tr[p].left,tr[p].right);
}

template <typename cactus>
cactus min_leftist_tree<cactus>::min_in(int p){
	p=get_root(p);
	return tr[p].v;
}

