class inverse_element{
	private:
		int MOD_P;
		int ie[MAXN+3];
		void init(const int range);
		const int query_in(const int a);
	public:
		explicit inverse_element(const int P);
		explicit inverse_element(const int P,const int range);
		const int query(const int a);
		const int operator[](const int a);
};

void inverse_element::init(const int range){
	ie[0]=1;
	ie[1]=1;
	for(int i=2;i<=range;i++){
		ie[i]=((MOD_P-MOD_P/i)*ie[(MOD_P%i)])%MOD_P;
	}
}

const int inverse_element::query_in(const int a){
	return ie[a];
}

inverse_element::inverse_element(const int P){
	MOD_P=P;
	init(MOD_P-1);
}

inverse_element::inverse_element(const int P,const int range){
	MOD_P=P;
	init(range);
}

const int inverse_element::query(const int a){
	return ie[a];
}

const int inverse_element::operator[](const int a){
	return ie[a];
}

