template <typename cactus>
class discrete_array{//address starts from 1
	private:
		int n;
		int ax[MAXN];
		cactus d[MAXN];
		void init(cactus *a1,cactus *a2);
	public:
		explicit discrete_array(cactus *a1,cactus *a2);
		const SIZE_C size(void){return n;}
		int* operator()(const int addr);//points to the discreted array
		const cactus operator[](const int addr);//returns the original value
		int* operator+(const int addr);
};

template <typename cactus>
void discrete_array<cactus>::init(cactus *a1,cactus *a2){
	pair_c <cactus,int> a[MAXN];
	n=a2-a1;
	for(int i=1;i<=n;i++){
		a[i].x1=*a1;
		a[i].x2=i;
		a1++;
	}
	sort(a+1,a+n+1);
	int pt=1;
	d[1]=a[1].x1;
	ax[a[1].x2]=1;
	for(int i=2;i<=n;i++){
		if(a[i].x1==a[i-1].x1){
			ax[a[i].x2]=pt;
		}else{
			pt++;
			d[pt]=a[i].x1;
			ax[a[i].x2]=pt;
		}
	}
}

template <typename cactus>
discrete_array<cactus>::discrete_array(cactus *a1,cactus *a2){
	init(a1,a2);
}

template <typename cactus>
int* discrete_array<cactus>::operator()(const int addr){
	return ax+addr;
}

template <typename cactus>
int* discrete_array<cactus>::operator+(const int addr){
	return ax+addr;
}

template <typename cactus>
const cactus discrete_array<cactus>::operator[](const int addr){
	return d[addr];
}

