class t01_node{
	friend class trie01;
	private:
		int left;
		int right;
		int cnt;
		int size;
		t01_node(void);
		t01_node(int l,int r,int cnt_,int sz);
};

t01_node::t01_node(void){
	left=0;
	right=0;
	cnt=0;
	size=0;
}

t01_node::t01_node(int l,int r,int cnt_,int sz){
	left=l;
	right=r;
	cnt=cnt_;
	size=sz;
}



class trie01{
	private:
		int n;
		t01_node tr[MAXN];
		int szn;
		int new_node(void);
		int new_node(bool v,int pa,int l,int r);
		int find_p(int v);
		void insert_in(int v);
		bool del_in(int v);
		void self_add_in(void);
		int find_in(int v);
		int kth_in(int k);
		int rank_in(int v);
		int pre_in(int v);
		int suc_in(int v);
	public:
		trie01(void);
		const SIZE_C size(void);
		void insert(const int v);
		const bool del(const int v);
		void add(void);
		void operator++(void);
		const int find(const int v);
		const int kth(const int k);
		const int rank(const int v);
		const int pre(const int v);
		const int suc(const int v);
};

int trie01::new_node(void){
	n++;
	return n;
}

int trie01::new_node(bool v,int pa,int l,int r){
	n++;
	if(v){
		tr[pa].right=n;
	}else{
		tr[pa].left=n;
	}
	tr[n]=t01_node(l,r,0,0);
	return n;
}

int trie01::find_p(int v){
	int p=1;
	for(int i=MAXH;i>=0;i--){
		if(kth_bool(v,i)){
			p=tr[p].right;
		}else{
			p=tr[p].left;
		}
		if(p==0){
			return 0;
		}
	}
	return p;
}

void trie01::insert_in(int v){
	szn++;
	int p=1;
	int from;
	for(int i=MAXH;i>=0;i--){
		tr[p].size++;
		from=p;
		if(kth_bool(v,i)){
			p=tr[p].right;
		}else{
			p=tr[p].left;
		}
		if(p==0){
			p=new_node(kth_bool(v,i),from,0,0);
		}
	}
	tr[p].size++;
	tr[p].cnt++;
}

bool trie01::del_in(int v){
	int px=find_p(v);
	if(px){
		if(tr[px].cnt<1){
			return 0;
		}
		tr[px].cnt--;
		tr[px].size--;
		int p=1;
		for(int i=MAXH;i>=0;i--){
			tr[p].size--;
			if(kth_bool(v,i)){
				p=tr[p].right;
			}else{
				p=tr[p].left;
			}
		}
		szn--;
		return 1;
	}else{
		return 0;
	}
}

void trie01::self_add_in(void){
	int p=1;
	while(p){
		swap_c(tr[p].left,tr[p].right);
		p=tr[p].right;
	}
}

int trie01::find_in(int v){
	int px=find_p(v);
	if(px==0){
		return 0;
	}else{
		return tr[px].cnt;
	}
}

int trie01::kth_in(int k){
	int p=1;
	int rr=0;
	for(int i=MAXH;i>=0;i--){
		if(tr[tr[p].left].size<k){
			k-=tr[tr[p].left].size;
			p=tr[p].right;
			rr+=(1<<i);
		}else{
			p=tr[p].left;
		}
	}
	return rr;
}

int trie01::rank_in(int v){
	int ret=0;
	int p=1;
	for(int i=MAXH;i>=0;i--){
		if(kth_bool(v,i)){
			ret+=tr[tr[p].left].size;
			p=tr[p].right;
		}else{
			p=tr[p].left;
		}
		if(p==0){
			return 0;
		}
	}
	return ret+1;
}

int trie01::pre_in(int v){
	int xx=rank_in(v);
	if(xx==1||xx==0){
		return -INF;
	}
	return kth_in(xx-1);
}

int trie01::suc_in(int v){
	int xx=rank_in(v+1);
	if(xx){
		return kth_in(xx);
	}
	return INF;
}

trie01::trie01(void){
	n=1;
	tr[1]=t01_node(0,0,0,0);
}

const SIZE_C trie01::size(void){
	return szn;
}

void trie01::insert(const int v){
	insert_in(v);
}

const bool trie01::del(const int v){
	return del_in(v);
}

void trie01::add(void){
	self_add_in();
}

void trie01::operator++(void){
	self_add_in();
}

const int trie01::find(const int v){
	return find_in(v);
}

const int trie01::kth(const int k){
	return kth_in(k);
}

const int trie01::rank(const int v){
	return rank_in(v);
}

const int trie01::pre(const int v){
	return pre_in(v);
}

const int trie01::suc(const int v){
	return suc_in(v);
}

void operator++(trie01 t){
	t.add();
}

