template <typename cactus>
class exGCD{
	private:
		cactus a;
		cactus b;
		cactus gcdx;
		cactus d;//c=d*gcdx
		cactus c;
		cactus t_x;
		cactus t_y;
		cactus dx;
		cactus dy;
		void works(cactus t_a,cactus t_b);
		void pre_pair(void);
		void suc_pair(void);
		cactus find_x(cactus y);
		cactus find_y(cactus x);
	public:
		explicit exGCD(const cactus a_,const cactus b_,const cactus d_);
		const pair_c <cactus,cactus> solution(void);
		void previous(void);
		void next(void);
		const pair_c <cactus,cactus> operator()(void);
		const cactus x(const cactus y);
		const cactus y(const cactus x);
		const cactus x(void);
		const cactus y(void);
		void operator++(void);
		void operator--(void);
		void operator++(int);
		void operator--(int);
};

template <typename cactus>
void exGCD<cactus>::works(cactus t_a,cactus t_b){
	if(t_b==0){
		t_x=d;
		t_y=0;
		return;
	}
	works(t_b,t_a%t_b);
	cactus t;
	t=t_y;
	t_y=t_x-t_a/t_b*t_y;
	t_x=t;
}

template <typename cactus>
void exGCD<cactus>::pre_pair(void){
	t_x-=dx;
	t_y-=dy;
}

template <typename cactus>
void exGCD<cactus>::suc_pair(void){
	t_x+=dx;
	t_y+=dy;
}

template <typename cactus>
cactus exGCD<cactus>::find_x(cactus y){
	return (c-y*b)/a;
}

template <typename cactus>
cactus exGCD<cactus>::find_y(cactus x){
	return (c-x*a)/b;
}

template <typename cactus>
exGCD<cactus>::exGCD(const cactus a_,const cactus b_,const cactus d_){
	a=a_;
	b=b_;
	gcdx=gcd_c(a,b);
	d=d_/gcdx;
	c=d*gcdx;
	works(a,b);
	cactus d=lcm_c(a,b);
	dx=d/a;
	dy=-d/b;
}

template <typename cactus>
const pair_c <cactus,cactus> exGCD<cactus>::solution(void){
	return pair_c<cactus,cactus>(t_x,t_y);
}

template <typename cactus>
void exGCD<cactus>::previous(void){
	pre_pair();
}

template <typename cactus>
void exGCD<cactus>::next(void){
	suc_pair();
}

template <typename cactus>
const pair_c <cactus,cactus> exGCD<cactus>::operator()(void){
	return solution();
}

template <typename cactus>
const cactus exGCD<cactus>::x(const cactus y){
	return find_x(y);
}

template <typename cactus>
const cactus exGCD<cactus>::y(const cactus x){
	return find_y(x);
}

template <typename cactus>
const cactus exGCD<cactus>::x(void){
	return t_x;
}

template <typename cactus>
const cactus exGCD<cactus>::y(void){
	return t_y;
}

template <typename cactus>
void exGCD<cactus>::operator++(void){
	suc_pair();
}

template <typename cactus>
void exGCD<cactus>::operator--(void){
	pre_pair();
}


template <typename cactus>
void exGCD<cactus>::operator++(int){
	suc_pair();
}

template <typename cactus>
void exGCD<cactus>::operator--(int){
	pre_pair();
}

