		area_sum_node<cactus> nd[MAXN];
		pair_c<cactus,int> x_st[MAXN];
		int dn[MAXN];
		cactus px[MAXN];
		int num;
		area_sum_ndtr<cactus> tr[MAXN];
		cactus ret;
		void build(int l,int r,int p);
		void add_e(int p,int l,int r);
		void mns_e(int p,int l,int r);
		void ins_x(int l,int r,int lx,int rx,int p);
		void del_x(int l,int r,int lx,int rx,int p);
		cactus sum_(void);
		void init(array_c<area_sum_node<cactus>,MAXN>& arr);
		void discrete(void);
		void moveline(void);
		cactus sum_in(void);
		explicit area_sum_calc(array_c<area_sum_node<cactus>,MAXN>& arr,int n_);
		cactus sum(void);
};

template <typename cactus>
void area_sum_calc<cactus>::build(int l,int r,int p){
	if(l==r){
		tr[p].s=px[l+1]-px[l];
		return;
	}
	int mid=(l+r)>>1;
	build(l,mid,p<<1);
	build(mid+1,r,(p<<1)+1);
	tr[p].s=tr[p<<1].s+tr[(p<<1)+1].s;
}

template <typename cactus>
void area_sum_calc<cactus>::add_e(int p,int l,int r){
	if(tr[p].cnt==0){
		tr[p].cnt++;
		tr[p].sum=tr[p].s;
	}else{
		tr[p].cnt++;
		return;
	}
}

template <typename cactus>
void area_sum_calc<cactus>::mns_e(int p,int l,int r){
	if(tr[p].cnt==1){
		tr[p].cnt--;
		if(l!=r){
			tr[p].sum=tr[p<<1].sum+tr[(p<<1)+1].sum;
		}else{
			tr[p].sum=0;
		}
	}else{
		tr[p].cnt--;
		return;
	}
}

template <typename cactus>
void area_sum_calc<cactus>::ins_x(int l,int r,int lx,int rx,int p){
	if(inrange(l,r,lx,rx)){
		add_e(p,l,r);
		return;
	}
	if(outofrange(l,r,lx,rx)){
		return;
	}
	int mid=(l+r)>>1;
	ins_x(l,mid,lx,rx,p<<1);
	ins_x(mid+1,r,lx,rx,(p<<1)+1);
	if(tr[p].cnt==0){
		tr[p].sum=tr[p<<1].sum+tr[(p<<1)+1].sum;
	}
}

template <typename cactus>
void area_sum_calc<cactus>::del_x(int l,int r,int lx,int rx,int p){
	if(inrange(l,r,lx,rx)){
		mns_e(p,l,r);
		return;
	}
	if(outofrange(l,r,lx,rx)){
		return;
	}
	int mid=(l+r)>>1;
	del_x(l,mid,lx,rx,p<<1);
	del_x(mid+1,r,lx,rx,(p<<1)+1);
	if(tr[p].cnt==0){
		tr[p].sum=tr[p<<1].sum+tr[(p<<1)+1].sum;
	}
}

template <typename cactus>
cactus area_sum_calc<cactus>::sum_(void){
	return tr[1].sum;
}

template <typename cactus>
void area_sum_calc<cactus>::init(array_c<area_sum_node<cactus>,MAXN>& arr){
	nx=n*2;
	for(int i=1;i<=nx;i++){
		nd[i]=arr[i];
		if(i&1){
			x_st[i].x1=nd[i].xl;
			x_st[i].x2=i;
			x_st[i+1].x1=nd[i].xr;
			x_st[i+1].x2=i+1;
		}
	}
	discrete();
	build(1,num,1);
}

template <typename cactus>
void area_sum_calc<cactus>::discrete(void){
	sort(x_st+1,x_st+nx+1);
	sort(nd+1,nd+nx+1);
	pt=1;
	dn[x_st[1].x2]=1;
	px[1]=x_st[1].x1;
	for(int i=2;i<=nx;i++){
		if(x_st[i].x1!=x_st[i-1].x1){
			pt++;
			px[pt]=x_st[pt].x1;
		}
		dn[x_st[pt].x2]=pt;
	}
	num=pt-1;
}

template <typename cactus>
void area_sum_calc<cactus>::moveline(void){
	ins_x(1,num,dn[nd[1].ix*2-1],dn[nd[1].ix*2]-1,1);
	for(int i=2;i<nx;i++){
		if(nd[i].sgn){
			ins_x(1,num,dn[nd[i].ix*2-1],dn[nd[i].ix*2]-1,1);
		}else{
			del_x(1,num,dn[nd[i].ix*2-1],dn[nd[i].ix*2]-1,1);
		}
		if(nd[i].y!=nd[i-1].y){
			ret+=sum_()*(nd[i].y-nd[i-1].y);
		}
	}
	ret+=sum_()*(nd[nx].y-nd[nx-1].y);
}

template <typename cactus>
cactus area_sum_calc<cactus>::sum_in(void){
	moveline();
	return ret;
}

template <typename cactus>
area_sum_calc<cactus>::area_sum_calc(array_c<area_sum_node<cactus>,MAXN>& arr,int n_){
	n=n_;
	ret=0;
	init(arr);
}

template <typename cactus>
cactus area_sum_calc<cactus>::sum(void){
	return sum_in();
}



