class AC_automaton_node{
	friend class AC_automaton;
	private:
		int ch[52];
		int fail;
		int cnt;
		int in;
		int vis;
		int ans;
		AC_automaton_node(void){}
		int& operator[](int addr){return ch[addr];}
};

class AC_automaton{
	private:
		const int MAXCHSZ=52;
		int n;
		int num;
		bool flag;
		int ptx[MAXN];
		array_c<> ret;
		AC_automaton_node tr[MAXN];
		queue_c <int> q;
		int transxc(char c);
		int new_node(void);
		bool ins(string s);
		bool ins(char* s);
		void buildin(void);
		void query(string s);
		void query(char *s);
		void topo(void);
	public:
		AC_automaton(void);
		const SIZE_C size(void);
		const SIZE_C editable(void);
		const bool insert(const string s);
		const bool insert(const char* s);
		const array_c<>& match(const string s);
		const array_c<>& match(const char* s);
};

int AC_automaton::transxc(char c){
	if(c>='a'){
		return c-'a';
	}else{
		return c-'A'+26;
	}
}

int AC_automaton::new_node(void){
	n++;
	return n;
}

bool AC_automaton::ins(string s){
	if(flag){
		return 0;
	}
	int p=0;
	int len=s.length();
	for(int i=0;i<len;i++){
		if(tr[p][transxc(s[i])]){
			p=tr[p][transxc(s[i])];
		}else{
			tr[p][transxc(s[i])]=new_node();
			p=tr[p][transxc(s[i])];
		}
	}
	tr[p].cnt++;
	num++;
	ptx[num]=p;
	return 1;
}

bool AC_automaton::ins(char* s){
	if(flag){
		return 0;
	}
	int pt=0;
	int len=strlen(s);
	for(int i=0;i<len;i++){
		if(tr[pt][transxc(*s)]){
			pt=tr[pt][transxc(*s)];
		}else{
			tr[pt][transxc(*s)]=new_node();
			pt=tr[pt][transxc(*s)];
		}
		s++;
	}
	tr[pt].cnt++;
	num++;
	ptx[num]=pt;
	return 1;
}

void AC_automaton::buildin(void){
	ret.n=num;
	flag=1;
	q.clear();
	for(int i=0;i<MAXCHSZ;i++){
		if(tr[0][i]){
			q.insert(tr[0][i]);
		}
	}
	int t;
	while(!q.empty()){
		t=q.front();
		q.pop();
		for(int i=0;i<MAXCHSZ;i++){
			if(tr[t][i]){
				tr[tr[t][i]].fail=tr[tr[t].fail][i];
				tr[tr[tr[t].fail][i]].in++;
				q.insert(tr[t][i]);
			}else{
				tr[t][i]=tr[tr[t].fail][i];
			}
		}
	}
}

void AC_automaton::query(string s){
	int pt=0;
	int len=s.length();
	for(int i=0;i<len;i++){
		pt=tr[pt][transxc(s[i])];
		tr[pt].vis+=(bool)tr[pt].cnt;
		tr[pt].ans++;
	}
}

void AC_automaton::query(char *s){
	int pt=0;
	int len=strlen(s);
	for(int i=0;i<len;i++){
		pt=tr[pt][transxc(*s)];
		tr[pt].vis+=(bool)tr[pt].cnt;
		tr[pt].ans++;
		s++;
	}
}

void AC_automaton::topo(void){
	q.clear();
	int inx[MAXN];
	for(int i=1;i<=n;i++){
		inx[i]=tr[i].in;
		if(!tr[i].in){
			q.insert(i);
		}
	}
	int j,f;
	while(!q.empty()){
		j=q.front();
		q.pop();
		f=tr[j].fail;
		if(tr[f].cnt){
			tr[f].vis+=tr[j].ans;
		}
		tr[f].ans+=tr[j].ans;
		inx[f]--;
		if(!inx[f]){
			q.insert(f);
		}
	}
	for(int i=1;i<=num;i++){
		ret[i]=tr[ptx[i]].vis;
	}
}

AC_automaton::AC_automaton(void){
	n=0;
	flag=0;
	num=0;
}

const SIZE_C AC_automaton::size(void){
	return num;
}

const SIZE_C AC_automaton::editable(void){
	return flag;
}

const bool AC_automaton::insert(const string s){
	return ins(s);
}

const bool AC_automaton::insert(const char* s){
	return ins(s);
}

const array_c<>& AC_automaton::match(const string s){
	if(!flag){
		buildin();
		flag=1;
	}
	query(s);
	topo();
	return ret;
}

const array_c<>& AC_automaton::match(const char* s){
	if(!flag){
		buildin();
		flag=1;
	}
	query(s);
	topo();
	return ret;
}



