#define LCT link_cut_trees
template <typename cactus,cactus (*fx)(cactus,cactus)>
class lct_node{
	friend class link_cut_trees<cactus,fx>;
	private:
		int left;
		int right;
		int p;
		cactus v;
		bool tag;//reverse
		int sz;
		lct_node(void);
		lct_node(int l,int r,int pa,cactus val,bool rtag,int size);
};

template <typename cactus,cactus (*fx)(cactus,cactus)>
lct_node<cactus,fx>::lct_node(void){
	left=0;
	right=0;
	p=0;
	tag=0;
	sz=0;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
lct_node<cactus,fx>::lct_node(int l,int r,int pa,cactus val,bool rtag,int size){
	left=l;
	right=r;
	p=pa;
	v=val;
	tag=rtag;
	sz=size;
}



template <typename cactus,cactus (*fx)(cactus,cactus)>
class link_cut_trees{
	private:
		int n;
		cactus a[MAXN];
		lct_node<cactus,fx> tr[MAXN];
		bool lrson(int p);
		bool isroot(int p);
		void pushdown(int p);
		void pushup(int p);
		void update(int p);
		void downdate(int p);
		void lr_rotate(int p);
		void splay(int p);
		int access(int p);
		int find_root_p(int p);
		void make_root(int p);
		void split(int p1,int p2);
		int root_in(int p);
		bool find_in(int p1,int p2);
		void cut_unlocked_in(int p1,int p2);
		bool cut_in(int p1,int p2);
		void link_unlocked_in(int p1,int p2);
		bool link_in(int p1,int p2);
		cactus sum_unlocked_in(int p1,int p2);
		cactus sum_in(int p1,int p2);
		void replace_in(int p,cactus v);
		void add_in(int p,cactus v);
		void minus_in(int p,cactus v);
		void renew_in(int p);
	public:
		explicit link_cut_trees(const int num);
		explicit link_cut_trees(cactus* a1,cactus* a2);
		const SIZE_C size(void);
		const int operator()(const int p);
