		const bool link(const int p1,const int p2);
		const cactus sum_unlocked(const int p1,const int p2);
		const cactus sum(const int p1,const int p2);
		void replace(const int p,const cactus v);
		void add(const int p,const cactus v);
		void minus(const int p,const cactus v);
		cactus& operator[](const int addr);
		cactus& value(const int p);
		void renew(const int p);
};

template <typename cactus,cactus (*fx)(cactus,cactus)>
bool link_cut_trees<cactus,fx>::lrson(int p){
	return p==tr[tr[p].p].right;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
bool link_cut_trees<cactus,fx>::isroot(int p){
	return (p!=tr[tr[p].p].left)&&(p!=tr[tr[p].p].right)&&p;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::pushdown(int p){
	if(tr[p].tag){
		tr[p].tag=0;
		if(tr[p].left){
			swap_c(tr[tr[p].left].left,tr[tr[p].left].right);
			tr[tr[p].left].tag^=1;
		}
		if(tr[p].right){
			swap_c(tr[tr[p].right].left,tr[tr[p].right].right);
			tr[tr[p].right].tag^=1;
		}
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::pushup(int p){
	tr[0].sz=tr[0].v=0;
	tr[p].v=fx(tr[tr[p].left].v,fx(tr[tr[p].right].v,a[p]));
	tr[p].sz=tr[tr[p].left].sz+tr[tr[p].right].sz+1;
	tr[0].sz=tr[0].v=0;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::update(int p){
	if(!isroot(p)){
		update(tr[p].p);
	}
	pushdown(p);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::downdate(int p){
	pushup(p);
	if(!isroot(p)){
		downdate(tr[p].p);
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::lr_rotate(int p){
	int pt=tr[p].p;
	int f=tr[pt].p;
	if(lrson(p)){
		if(!isroot(pt)){
			if(lrson(pt)){
				tr[f].right=p;
			}else{
				tr[f].left=p;
			}
		}
		tr[p].p=f;
		tr[pt].p=p;
		tr[pt].right=tr[p].left;
		if(tr[p].left){
			tr[tr[p].left].p=pt;
		}
		tr[p].left=pt;
		pushup(pt);
		pushup(p);
	}else{
		if(!isroot(pt)){
			if(lrson(pt)){
				tr[f].right=p;
			}else{
				tr[f].left=p;
			}
		}
		tr[p].p=f;
		tr[pt].p=p;
		tr[pt].left=tr[p].right;
		if(tr[p].right){
			tr[tr[p].right].p=pt;
		}
		tr[p].right=pt;
		pushup(pt);
		pushup(p);
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::splay(int p){
	update(p);
	pushdown(tr[p].left);
	pushdown(tr[p].right);
	int f;
	while(!isroot(p)){
		f=tr[p].p;
		if(f&&!isroot(f)){
			lr_rotate(lrson(p)==lrson(f)?f:p);
		}
		if(!isroot(p)){
			lr_rotate(p);
		}
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
int link_cut_trees<cactus,fx>::access(int p){
	int f=0;
	while(p){
		splay(p);
		tr[p].right=f;
		pushup(p);
		f=p;
		p=tr[p].p;
	}
	return f;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
int link_cut_trees<cactus,fx>::find_root_p(int p){
	access(p);
	splay(p);
	pushdown(p);
	while(tr[p].left){
		p=tr[p].left;
		pushdown(p);
	}
	splay(p);
	return p;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::make_root(int p){
	p=access(p);
	tr[p].tag^=1;
	swap_c(tr[p].left,tr[p].right);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::split(int p1,int p2){
	make_root(p1);
	access(p2);
	splay(p2);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
int link_cut_trees<cactus,fx>::root_in(int p){
	return find_root_p(p);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
bool link_cut_trees<cactus,fx>::find_in(int p1,int p2){
	return find_root_p(p1)==find_root_p(p2);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::cut_unlocked_in(int p1,int p2){
	make_root(p1);
	find_root_p(p2);
	tr[p2].p=0;
	tr[p1].right=0;
	pushup(p1);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
bool link_cut_trees<cactus,fx>::cut_in(int p1,int p2){
	make_root(p1);
	if(find_root_p(p2)!=p1||tr[p1].sz>2){
		return 0;
	}else{
		tr[p2].p=0;
		tr[p1].right=0;
		pushup(p1);
		return 1;
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::link_unlocked_in(int p1,int p2){
	make_root(p1);
	splay(p1);
	tr[p1].p=p2;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
bool link_cut_trees<cactus,fx>::link_in(int p1,int p2){
	if(find_root_p(p1)!=find_root_p(p2)){
		make_root(p1);
		splay(p1);
		tr[p1].p=p2;
		return 1;
	}else{
		return 0;
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
cactus link_cut_trees<cactus,fx>::sum_unlocked_in(int p1,int p2){
	split(p1,p2);
	return tr[p2].v;
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
cactus link_cut_trees<cactus,fx>::sum_in(int p1,int p2){
	if(p1==p2){
		return a[p1];
	}else{
		if(find_root_p(p1)==find_root_p(p2)){
			split(p1,p2);
			return tr[p2].v;
		}else{
			return 0;
		}
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::replace_in(int p,cactus v){
	splay(p);
	a[p]=v;
	pushup(p);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::add_in(int p,cactus v){
	splay(p);
	a[p]+=v;
	pushup(p);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::minus_in(int p,cactus v){
	splay(p);
	a[p]-=v;
	pushup(p);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
void link_cut_trees<cactus,fx>::renew_in(int p){
	splay(p);
	pushup(p);
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
link_cut_trees<cactus,fx>::link_cut_trees(const int num){
	n=num;
	for(int i=1;i<=n;i++){
		tr[i]=lct_node<cactus,fx>(0,0,0,0,0,1);
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
link_cut_trees<cactus,fx>::link_cut_trees(cactus* a1,cactus* a2){
	n=a2-a1;
	cactus *ax=a1;
	for(int i=1;i<=n;i++){
		a[i]=*ax;
		ax++;
	}
	for(int i=1;i<=n;i++){
		tr[i]=lct_node<cactus,fx>(0,0,0,a[i],0,1);
	}
}

template <typename cactus,cactus (*fx)(cactus,cactus)>
const SIZE_C link_cut_trees<cactus,fx>::size(void){
	return n;
}

