class map_node{
	friend class directed_graph;
	friend class undirected_graph;
	private:
		int from;
		int to;
		int val;
		int nex;
		map_node(void);
		map_node(const int u,const int v,const int w,const int next);
	public:
		const bool operator>(const map_node mn)const;
		const bool operator<(const map_node mn)const;
};

map_node::map_node(void){
	from=0;
	to=0;
	val=0;
	nex=-1;
}

map_node::map_node(const int u,const int v,const int w,const int next){
	from=u;
	to=v;
	val=w;
	nex=next;
}

const bool map_node::operator>(const map_node mn)const{
	return val>mn.val;
}

const bool map_node::operator<(const map_node mn)const{
	return val<mn.val;
}



class directed_graph{//due to the structure, numbers start from 1
	private:
		int num;
		int n;
		int root[MAXNUM+5];
		map_node m[MAXN];
		int timer;
		int tx;
		bool neg;
		bool vis[MAXN];
		bool ins[MAXN];
		int dfn[MAXN];
		int low[MAXN];
		array_c<> dis;
		array_c<> arr_scc;
		stack_c<int> st;

		const array_c<>& dijkstra(const int s);
		const array_c<>& spfa(const int s);
		bool scctarjan(int p,int from);
	public:
		directed_graph(void);
		directed_graph(const int size);
		const SIZE_C size(void);
		void connect(const int from,const int to,const int value);
		const array_c<>& shortest_path(const int s);
		const array_c<>& SCC(void);
};

const array_c<>& directed_graph::dijkstra(const int s){
	dis.n=num;
	for(int i=0;i<MAXNUM;i++){
		dis[i]=INF;
		vis[i]=0;
	}
	dis[s]=0;
	dis[0]=num;
	if(s<1||s>num){
		return dis;
	}
	small_heap <pair_c <int,int> > hp;
	int x=root[s];
	pair_c <int,int> cur;
	while(x!=-1){
		hp.insert(pair_c <int,int>(m[x].val,m[x].to));
		dis[m[x].to]=m[x].val;
		x=m[x].nex;
	}
	while(!hp.empty()){
		cur=hp.top();
		hp.pop();
		x=root[cur.x2];
		if(vis[cur.x2]){
			continue;
		}
		vis[cur.x2]=1;
		while(x!=-1){
			if(cur.x1+m[x].val<dis[m[x].to]){
				dis[m[x].to]=cur.x1+m[x].val;
				hp.insert(pair_c <int,int> (dis[m[x].to],m[x].to));
			}
			x=m[x].nex;
		}
	}
	return dis;
}

const array_c<>& directed_graph::spfa(const int s){
	queue_c <int> q;
	int inq[MAXNUM];
	dis.n=num;
	dis[0]=num;
	for(int i=0;i<MAXNUM;i++){
		dis[i]=INF;
		vis[i]=0;
		inq[i]=0;
	}
	dis[s]=0;
	q.insert(s);
	int cur;
	int cx;
	while(!q.empty()){
		cur=q.front();
		q.pop();
		vis[cur]=0;
		cx=root[cur];
		if(inq[cur]>num){
			dis[0]=0;
			return dis;
		}
		while(cx!=-1){
			if(dis[m[cx].to]>dis[cur]+m[cx].val){
				if(!vis[m[cx].to]){
					q.insert(m[cx].to);
					inq[m[cx].to]++;
				}
				dis[m[cx].to]=dis[cur]+m[cx].val;
				vis[m[cx].to]=1;
			}
			cx=m[cx].nex;
		}
	}
	return dis;
}

bool directed_graph::scctarjan(int p,int from){
	if(vis[p]){
		return 0;
	}
	vis[p]=1;
	ins[p]=1;
	timer++;
	dfn[p]=low[p]=timer;
	st.insert(p);
	for(int px=root[p];px>0;px=m[px].nex){
		if(scctarjan(m[px].to,p)){
			if(low[p]>low[m[px].to]){
				low[p]=low[m[px].to];
			}
		}else{
			if(ins[m[px].to]){
				if(low[p]>dfn[m[px].to]){
					low[p]=dfn[m[px].to];
				}
			}
		}
	}
	if(dfn[p]==low[p]){
		int t;
		tx++;
		while(1){
			t=st.top();
			st.pop();
			ins[t]=0;
			arr_scc[t]=tx;
			if(t==p){
				return 1;
			}
		}
	}
	return 1;
}

directed_graph::directed_graph(void){
	num=MAXNUM;
	neg=0;
	n=0;
	for(int i=0;i<MAXNUM;i++){
		root[i]=-1;
	}
}

directed_graph::directed_graph(const int size){
	num=size;
	neg=0;
	n=0;
	for(int i=0;i<MAXNUM;i++){
		root[i]=-1;
	}
}

const SIZE_C directed_graph::size(void){
	return n;
}

void directed_graph::connect(const int from,const int to,const int value){
	if(from<1||to<1||from>num||to>num){
		return;
	}else{
		m[n]=map_node(from,to,value,root[from]);
		root[from]=n;
		n++;
		if(value<0){
			neg=1;
		}
	}
}

const array_c<>& directed_graph::shortest_path(const int s){
	if(neg){
		return spfa(s);
	}else{
		return dijkstra(s);
	}
}

const array_c<>& directed_graph::SCC(void){
	for(int i=1;i<=num;i++){
		vis[i]=0;
		ins[i]=0;
	}
	arr_scc.n=num;
	timer=0;
	tx=0;
	for(int i=1;i<=num;i++){
		scctarjan(i,-1);
	}
	return arr_scc;
}



class undirected_graph{
	private:
		int num;//number of points (length of root)
		int n;//number of edges (length of m)
		int timer;
		array_c<> dis;
		int root[MAXNUM+5];//the root of edges
		int back_root[MAXNUM+5];//how many sub_trees there are
		map_node m[MAXN];//map edges
		bool neg;//if there are negative edges
		bool vis[MAXN];//visited
		map_node edge_sort[MAXN];//edges for kruskal
		int en;//size for kruskal
		int dfn[MAXNUM];//dfn for dfs
		int low[MAXNUM];//low for tarjan
		array_c<> ret_v;//array for returning vertexes
		array_c<pair_c<int,int> > ret_e;//array for returning edges

		void clear_vis(void);
		const array_c<>& dijkstra(const int s);
		const array_c<>& spfa(const int s);
		const int kruskal(void);
		bool cut_vertex_tarjan(int p,int from);
		bool cut_edge_tarjan(int p,int from);
	public:
		undirected_graph(void);
		undirected_graph(const int size);
		const SIZE_C size(void);
		void connect(const int from,const int to,const int value);
		const array_c<>& shortest_path(const int s);
		const int MST(void);
		const array_c<>& cut_vertex(void);
		const array_c<pair_c<int,int> >& cut_edge(void);
};

