	int x=root[s];
	pair_c <int,int> cur;
	while(x!=-1){
		hp.insert(pair_c <int,int>(m[x].val,m[x].to));
		dis[m[x].to]=m[x].val;
		x=m[x].nex;
	}
	while(!hp.empty()){
		cur=hp.top();
		hp.pop();
		x=root[cur.x2];
		if(vis[cur.x2]){
			continue;
		}
		vis[cur.x2]=1;
		while(x!=-1){
			if(cur.x1+m[x].val<dis[m[x].to]){
				dis[m[x].to]=cur.x1+m[x].val;
				hp.insert(pair_c <int,int> (dis[m[x].to],m[x].to));
			}
