const array_c<>& undirected_graph::spfa(const int s){
	queue_c <int> q;
	int inq[MAXNUM];
	dis.n=num;
	dis[0]=num;
	for(int i=0;i<MAXNUM;i++){
		dis[i]=INF;
		vis[i]=0;
		inq[i]=0;
	}
	dis[s]=0;
	q.insert(s);
	int cur;
	int cx;
	while(!q.empty()){
		cur=q.front();
		q.pop();
		vis[cur]=0;
		cx=root[cur];
		if(inq[cur]>num){
			dis[0]=0;
			return dis;
		}
		while(cx!=-1){
			if(dis[m[cx].to]>dis[cur]+m[cx].val){
				if(!vis[m[cx].to]){
					q.insert(m[cx].to);
					inq[m[cx].to]++;
				}
				dis[m[cx].to]=dis[cur]+m[cx].val;
				vis[m[cx].to]=1;
			}
			cx=m[cx].nex;
		}
	}
	return dis;
}

const int undirected_graph::kruskal(void){
	union_set u;
	sort(edge_sort,edge_sort+en);
	int cnt=0,ret=0;
	for(int i=0;i<en;i++){
		if(u.relate(edge_sort[i].from,edge_sort[i].to)){
			continue;
		}else{
			cnt++;
			u.merge(edge_sort[i].from,edge_sort[i].to);
			ret+=edge_sort[i].val;
			if(cnt==num){
				return ret;
			}
		}
	}
	return INF;
}

bool undirected_graph::cut_vertex_tarjan(int p,int from){
	if(vis[p]){
		return 0;
	}
	vis[p]=1;
	timer++;
	int child=0;
	dfn[p]=timer;
	low[p]=timer;
	bool flag=0;
	for(int px=root[p];px!=-1;px=m[px].nex){
		if(m[px].to!=from){
			if(cut_vertex_tarjan(m[px].to,p)){
				if(low[m[px].to]<low[p]){
					low[p]=low[m[px].to];
				}
				child++;
				if(low[m[px].to]>=dfn[p]){
					flag=1;
				}
			}else{
				if(dfn[m[px].to]<low[p]){
					low[p]=dfn[m[px].to];
				}
			}
		}
	}
	if(from==-1){
		if(child>1){
			ret_v.insert(p);
		}
	}else{
		if(flag){
			ret_v.insert(p);
		}
	}
	return 1;
}

bool undirected_graph::cut_edge_tarjan(int p,int from){
	if(vis[p]){
		return 0;
	}
	timer++;
	dfn[p]=low[p]=timer;
	vis[p]=1;
	for(int px=root[p];px!=-1;px=m[px].nex){
		if(m[px].to!=from){
			if(cut_edge_tarjan(m[px].to,p)){
				if(low[p]>low[m[px].to]){
					low[p]=low[m[px].to];
				}
				if(low[m[px].to]>dfn[p]){
					ret_e.insert(pair_c<int,int>(p,m[px].to));
				}
			}else{
				if(low[p]>dfn[m[px].to]){
					low[p]=dfn[m[px].to];
				}
			}
		}
	}
	return 1;
}

