void undirected_graph::connect(const int from,const int to,const int value){
	if(from<1||to<1||from>num||to>num){
		return;
	}else{
		m[n]=map_node(from,to,value,root[from]);
		root[from]=n;
		n++;
		m[n]=map_node(to,from,value,root[to]);
		root[to]=n;
		n++;
		if(value<0){
			neg=1;
		}
		edge_sort[en]=map_node(from,to,value,-1);
		en++;
	}
}

const array_c<>& undirected_graph::shortest_path(const int s){
	if(neg){
		return spfa(s);
	}else{
		return dijkstra(s);
	}
}

const int undirected_graph::MST(void){
	return kruskal();
}

const array_c<>& undirected_graph::cut_vertex(void){
	clear_vis();
	ret_v.n=0;
	for(int i=1;i<=num;i++){
		cut_vertex_tarjan(i,-1);
	}
	return ret_v;
}

const array_c<pair_c<int,int> >& undirected_graph::cut_edge(void){
	clear_vis();
	ret_e.n=0;
	for(int i=1;i<=num;i++){
		cut_edge_tarjan(i,-1);
	}
	return ret_e;
}

