void persistent_ascii_trie::simple_insert_in(string s){
	num++;
	root[num]=copy_node(root[num-1]);
	int pt=root[num];
	int len=s.length();
	for(int i=0,j;i<len;i++){
		j=trans(s[i]);
		tr[pt].sz++;
		if(tr[pt].ch[j]){
			tr[pt].ch[j]=copy_node(tr[pt].ch[j]);
		}else{
			tr[pt].ch[j]=new_node();
		}
		pt=tr[pt].ch[j];
	}
	tr[pt].sz++;
	tr[pt].cnt++;
}

