class dinic_node{
	friend class dinic;
	private:
		int to;
		int flow;
		int cap;
		int nex;
		dinic_node(void);
		dinic_node(int to_,int flow_,int cap_,int nex_);
};

dinic_node::dinic_node(void){
	return;
}

dinic_node::dinic_node(int to_,int flow_,int cap_,int nex_){
	to=to_;
	flow=flow_;
	cap=cap_;
	nex=nex_;
}



class dinic{
	private:
		dinic_node m[MAXN];
		int cnt;
		int root[MAXNUM];
		int n;
		int s_,t_;
		int cur[MAXNUM];
		int dep[MAXNUM];
		bool vis[MAXNUM];
		queue_c <int> q;
		bool bfs(void);
		int dfs(int u,int flow);
		void dinic_in(void);
	public:
		int maxflow;
	public:
		explicit dinic(const int num);
		const SIZE_C size(void);
		void connect(const int from,const int to,const int flow);
		const int max_flow(const int s,const int t);
};

bool dinic::bfs(void){
	for(int i=1;i<=n;i++){
		dep[i]=INF;
	}
	dep[s_]=0;
	q.insert(s_);
	int tp;
	while(!q.empty()){
		tp=q.front();
		q.pop();
		for(int p=root[tp];p!=-1;p=m[p].nex){
			if(dep[m[p].to]==INF&&m[p].flow<m[p].cap){
				dep[m[p].to]=dep[tp]+1;
			}
		}
	}
	return dep[t_]!=INF;
}

int dinic::dfs(int u,int flow){
	if(u==t_||flow==0){
		return flow;
	}
	int d;
	int ret=0;
	for(int& p=cur[u];p!=-1;p=m[p].nex){
		if(dep[m[p].to]==dep[u]+1){
			d=dfs(m[p].to,min(flow-ret,m[p].cap-m[p].flow));
			ret+=d;
			m[p].flow+=d;
			m[p^1].flow-=d;
			if(flow==ret)break;
		}
	}
	return ret;
}

void dinic::dinic_in(void){
	while(bfs()){
		for(int i=1;i<=n;i++){
			cur[i]=root[i];
		}
		maxflow+=dfs(s_,INF);
	}
}

dinic::dinic(const int num){
	n=num;
	cnt=0;
	for(int i=1;i<=num;i++){
		root[i]=-1;
	}
}

const SIZE_C dinic::size(void){
	return n;
}

void dinic::connect(const int from,const int to,const int flow){
	m[cnt]=dinic_node(to,0,flow,root[from]);
	root[from]=cnt;
	cnt++;
	m[cnt]=dinic_node(from,0,0,root[to]);
	root[to]=cnt;
	cnt++;
}

const int dinic::max_flow(const int s,const int t){
	maxflow=0;
	dinic_in();
	return maxflow;
}

