	friend class dinic_mcmf;
	private:
		int to;
		int flow;
		int cap;
		int cost;
		int nex;
		dinic_mcmf_node(void);
		dinic_mcmf_node(int to_,int flow_,int cap_,int cost_,int nex_);
};

dinic_mcmf_node::dinic_mcmf_node(void){
	return;
}

dinic_mcmf_node::dinic_mcmf_node(int to_,int flow_,int cap_,int cost_,int nex_){
	to=to_;
	flow=flow_;
	cap=cap_;
	cost=cost_;
	nex=nex_;
}



class dinic_mcmf{
	private:
		dinic_mcmf_node m[MAXN];
		int cnt;
		int n;
		int root[MAXN];
		queue_c <int> q;
		int cur[MAXN];
		int dis[MAXN];
		bool vis[MAXN];
		int s_,t_;
		const bool spfa(void);
		int dfs(int u,int flow);
		void dinic_in(void);
	public:
		int maxflow;
		int mincost;
	public:
		explicit dinic_mcmf(const int num);
		const SIZE_C size(void);
		void connect(const int from,const int to,const int flow,const int cost);
		const pair_c<int,int> mcmf(const int s,const int t);
};

const bool dinic_mcmf::spfa(void){
	for(int i=1;i<=n;i++){
		dis[i]=0x3fffffff;
		vis[i]=0;
	}
	dis[s_]=0;
	q.insert(s_);
	vis[s_]=1;
	int tp;
	while(!q.empty()){
		tp=q.front();
		vis[tp]=0;
		q.pop();
		for(int p=root[tp];p!=-1;p=m[p].nex){
			if(m[p].flow<m[p].cap&&dis[m[p].to]>dis[tp]+m[p].cost){
				dis[m[p].to]=dis[tp]+m[p].cost;
				if(!vis[m[p].to]){
					q.insert(m[p].to);
					vis[m[p].to]=1;
				}
			}
		}
	}
	return dis[t_]!=0x3fffffff;
}

int dinic_mcmf::dfs(int u,int flow){
	if(u==t_||flow==0){
		return flow;
	}
	int d=0,ret=0;
	vis[u]=1;
	for(int& p=cur[u];p!=-1;p=m[p].nex){
		if(!vis[m[p].to]&&dis[m[p].to]==dis[u]+m[p].cost){
			d=dfs(m[p].to,min(flow-ret,m[p].cap-m[p].flow));
			ret+=d;
			mincost+=m[p].cost*d;
			m[p].flow+=d;
			m[p^1].flow-=d;
			if(ret==flow)break;
		}
	}
	vis[u]=0;
	return ret;
}

void dinic_mcmf::dinic_in(void){
	while(spfa()){
		for(int i=1;i<=n;i++){
			cur[i]=root[i];
			vis[i]=0;
		}
		maxflow+=dfs(s_,INF);
	}
}

dinic_mcmf::dinic_mcmf(const int num){
	n=num;
	cnt=0;
	for(int i=1;i<=n;i++){
		root[i]=-1;
	}
}

const SIZE_C dinic_mcmf::size(void){
	return n;
}

void dinic_mcmf::connect(const int from,const int to,const int flow,const int cost){
	m[cnt]=dinic_mcmf_node(to,0,flow,cost,root[from]);
	root[from]=cnt;
	cnt++;
	m[cnt]=dinic_mcmf_node(from,0,0,cost,root[to]);
	root[to]=cnt;
	cnt++;
}

const pair_c<int,int> dinic_mcmf::mcmf(const int s,const int t){
	s_=s;
	t_=t;
	maxflow=0;
	mincost=0;
