class lc_segment{
	friend class max_line_segment_tree;
	friend class min_line_segment_tree;
	private:
		double k,b;
		lc_segment(void);
		lc_segment(double k_,double b_);
		lc_segment(double xl,double xr,double yl,double yr);
		const double fx(double x);
};

lc_segment::lc_segment(void){
	k=0.0;
	b=0.0;
}

lc_segment::lc_segment(double k_,double b_){
	k=k_;
	b=b_;
}

lc_segment::lc_segment(double xl,double xr,double yl,double yr){
	k=(yr-yl)/(xr-xl);
	b=yr-xr*k;
}

const double lc_segment::fx(double x){
	return k*x+b;
}



class max_line_segment_tree{
	private:
		lc_segment a[MAXN];
		int tr[MAXN*2];
		int cnt;
		int n;//range
		int cmp(double x,double y);
		pair_c<double,int> max(pair_c<double,int> x,pair_c<double,int> y);
		void build(int p,int l,int r);
		void pushdown(int p,int id,int l,int r);
		void insert_in(int p,int l,int r,int id,int lx,int rx);
		pair_c<double,int> query(int p,int l,int r,int px);
	public:
		explicit max_line_segment_tree(const int range);
		const SIZE_C size(void);
		const SIZE_C value_range(void);
		const int insert(const int xl,const int yl,const int xr,const int yr);
		const double max(const int p);
		const int max_segment(const int p);
};

int max_line_segment_tree::cmp(double x,double y){
	if(x-y>eps)return 1;
	if(y-x>eps)return -1;
	return 0;
}

pair_c<double,int> max_line_segment_tree::max(pair_c<double,int> x,pair_c<double,int> y){
	if(x.x2==0)return y;
	if(y.x2==0)return x;
	int c=cmp(x.x1,y.x1);
	if(c==1||(c==0&&x.x2<y.x2)){
		return x;
	}else{
		return y;
	}
}

void max_line_segment_tree::build(int p,int l,int r){
	tr[p]=0;
	if(l==r){
		return;
	}
	int mid=(l+r)>>1;
	build(p<<1,l,mid);
	build(p<<1|1,mid+1,r);
}

void max_line_segment_tree::pushdown(int p,int id,int l,int r){
	if(!id)return;
	if(tr[p]==0){
		tr[p]=id;
		return;
	}
	int mid=(l+r)>>1;
	int dmid=cmp(a[tr[p]].fx(mid),a[id].fx(mid));
	if(dmid==-1||(dmid==0&&tr[p]>id)){
		swap_c(tr[p],id);
	}
	int dl=cmp(a[tr[p]].fx(l),a[id].fx(l));
	int dr=cmp(a[tr[p]].fx(r),a[id].fx(r));
	if(dl==-1||(dl==0&&id<tr[p])){
		if(l^r)pushdown(p<<1,id,l,mid);
	}
	if(dr==-1||(dr==0&&id<tr[p])){
		if(l^r)pushdown(p<<1|1,id,mid+1,r);
	}
}

void max_line_segment_tree::insert_in(int p,int l,int r,int id,int lx,int rx){
	if(inrange(l,r,lx,rx)){
		pushdown(p,id,l,r);
		return;
	}
	if(outofrange(l,r,lx,rx)){
		return;
	}
	int mid=(l+r)>>1;
	insert_in(p<<1,l,mid,id,lx,rx);
	insert_in(p<<1|1,mid+1,r,id,lx,rx);
}

pair_c<double,int> max_line_segment_tree::query(int p,int l,int r,int px){
	if(l==r){
		return pair_c<double,int>(a[tr[p]].fx(px),tr[p]);
	}
	int mid=(l+r)>>1;
	pair_c<double,int> t=pair_c<double,int>(a[tr[p]].fx(px),tr[p]);
	if(px>mid){
		return max(query(p<<1|1,mid+1,r,px),t);
	}else{
		return max(query(p<<1,l,mid,px),t);
	}
}

max_line_segment_tree::max_line_segment_tree(const int range){
	n=range;
	build(1,1,n);
	cnt=0;
}

const SIZE_C max_line_segment_tree::size(void){
	return cnt;
}

const SIZE_C max_line_segment_tree::value_range(void){
	return n;
}

const int max_line_segment_tree::insert(const int xl,const int yl,const int xr,const int yr){
	cnt++;
	if(xl==xr){
		a[cnt]=lc_segment(0.0,max_c(yl,yr));
	}else{
		a[cnt]=lc_segment(xl,xr,yl,yr);
	}
	if(xl>xr){
		insert_in(1,1,n,cnt,xr,xl);
	}else{
		insert_in(1,1,n,cnt,xl,xr);
	}
	return cnt;
}

const double max_line_segment_tree::max(const int p){
	return query(1,1,n,p).x1;
}

const int max_line_segment_tree::max_segment(const int p){
	return query(1,1,n,p).x2;
}



